    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

files.types/learning.ts:
export type Field =
  | 'source'
  | 'translation'
  | 'transcription'
  | 'definition'
  | 'sourceExample'
  | 'targetExample'

export type Rating = 'known' | 'again'
export type Direction = 'ltr' | 'rtl'
export type Face = 'front' | 'back'

export interface Configuration {
  front: Field[]
  back: Field[]
}

export interface Preferences {
  configuration: Configuration
  shuffle: boolean
  version: number
}

export interface Presentation {
  field: Field
  requestedFields: Field[]
  text: string
  language: string
  direction: Direction
  fallback: boolean
}

export interface FlashcardItem {
  entryId: string
  learningVersion: number
  front: Presentation[]
  back: Presentation[]
}

export interface ItemsResponse {
  items: FlashcardItem[]
  unavailableEntryIds: string[]
}

export type Scope = { type: 'all' } | { type: 'manual'; entryIds: string[] }

export interface PrepareResponse {
  entryIds: string[]
  eligibleCount: number
  skippedCount: number
  fallbackCount: number
}

export interface EntryPreview {
  entryId: string
  source: string
  translation: string
}

export interface EntriesPage {
  entries: EntryPreview[]
  nextCursor: string | null
}

export interface Progress {
  total: number
  known: number
  again: number
  unstudied: number
}

export interface AttemptResponse {
  attemptId: string
  entryId: string
  learningVersion: number
  rating: Rating
}

export interface UndoResponse {
  attemptId: string
  entryId: string
  learningVersion: number
  rating: Rating | null
}

export type BackendErrorCode =
  | 'authentication_required'
  | 'dictionary_not_found'
  | 'shared_dictionary_not_found'
  | 'entry_not_found'
  | 'invalid_request'
  | 'version_conflict'
  | 'idempotency_conflict'
  | 'learning_version_conflict'
  | 'undo_conflict'
  | 'rate_limited'
  | 'service_unavailable'
  | 'internal_error'

/** Client-only code: the request timed out, so the server outcome is unknown. */
export type ErrorCode = BackendErrorCode | 'network_timeout'

files.utils/apiError.ts:
import type { ErrorCode } from '../types/learning'

export class ApiError extends Error {
  code: ErrorCode
  status: number
  correlationId: string
  retryAfterSeconds?: number

  constructor(code: ErrorCode, message: string, status: number, retryAfterSeconds?: number) {
    super(message)
    this.name = 'ApiError'
    this.code = code
    this.status = status
    this.correlationId = `corr-${Math.random().toString(36).slice(2, 10)}`
    this.retryAfterSeconds = retryAfterSeconds
  }
}

export function toApiError(error: unknown): ApiError {
  if (error instanceof ApiError) return error
  return new ApiError('internal_error', 'Unexpected error', 500)
}

export function isAccessLoss(error: ApiError): boolean {
  return (
    error.code === 'dictionary_not_found' ||
    error.code === 'shared_dictionary_not_found' ||
    error.code === 'authentication_required'
  )
}

export interface ErrorCopy {
  title: string
  message: string
}

/** User-facing copy. Never exposes codes, correlation IDs or backend internals. */
export function describeError(error: ApiError): ErrorCopy {
  switch (error.code) {
    case 'rate_limited':
      return {
        title: 'Too many requests right now',
        message: `Please wait ${error.retryAfterSeconds ?? 5} seconds, then try again.`,
      }
    case 'network_timeout':
      return {
        title: 'The connection timed out',
        message: 'Check your connection and try again.',
      }
    case 'service_unavailable':
      return {
        title: 'Training is temporarily unavailable',
        message: 'The learning service is not responding. Try again in a moment.',
      }
    case 'invalid_request':
      return {
        title: 'These settings could not be used',
        message: 'Adjust the selected fields or entries and try again.',
      }
    case 'authentication_required':
      return {
        title: 'Please sign in again',
        message: 'Your sign-in could not be confirmed, so nothing more can be saved.',
      }
    case 'dictionary_not_found':
    case 'shared_dictionary_not_found':
      return {
        title: 'This dictionary is no longer available',
        message: 'Access may have been removed or the dictionary was archived.',
      }
    case 'entry_not_found':
      return {
        title: 'This entry is no longer available',
        message: 'It was removed or archived.',
      }
    default:
      return {
        title: 'Something went wrong',
        message: 'We could not complete that request. Try again.',
      }
  }
}

