/**
 * Requests browser fullscreen. Must be called synchronously from a click handler.
 * Resolves false when unsupported, rejected, or when the designer simulates rejection.
 */
export function requestAppFullscreen(simulateReject: boolean): Promise<boolean> {
  if (simulateReject) return Promise.resolve(false)
  const el = document.documentElement
  if (!el.requestFullscreen || !document.fullscreenEnabled) return Promise.resolve(false)
  try {
    return el.requestFullscreen().then(
      () => true,
      () => false,
    )
  } catch {
    return Promise.resolve(false)
  }
}

export function exitAppFullscreen() {
  if (document.fullscreenElement && document.exitFullscreen) {
    document.exitFullscreen().catch(() => undefined)
  }
}

