import React from 'react'
import { InfoIcon, PlayIcon } from 'lucide-react'
import type { DictionaryRecord } from '../../../types/dictionary'
import type { Scenario } from '../../../types/demo'
import { describeError } from '../../../utils/apiError'
import { FIELD_LABELS, orderFields } from '../../../utils/flashcardFields'
import { exitAppFullscreen, requestAppFullscreen } from '../../../utils/fullscreen'
import { Button } from '../../Button'
import { Dialog, DialogActions } from '../../Dialog'
import { InlineAlert } from '../../InlineAlert'
import { Radio, RadioGroup } from '../../Radio'
import { FieldGroup } from './FieldGroup'
import { ManualSelection } from './ManualSelection'
import { PrepareSummary } from './PrepareSummary'
import { useFlashcardSetup } from './useFlashcardSetup'
import type { StartPayload } from './useFlashcardSetup'

interface SetupDialogProps {
  open: boolean
  onClose: () => void
  onStart: (payload: StartPayload, fullscreen: Promise<boolean>) => void
  dictionary: DictionaryRecord
  activeCount: number
  signedIn: boolean
  scenario: Scenario
}

export function SetupDialog({
  open,
  onClose,
  onStart,
  dictionary,
  activeCount,
  signedIn,
  scenario,
}: SetupDialogProps) {
  const setup = useFlashcardSetup({ open, signedIn, scenario, activeCount })

  const handleStart = async () => {
    // Fullscreen must be requested synchronously inside the click gesture.
    const fullscreen = requestAppFullscreen(scenario === 'fullscreenRejected')
    const payload = await setup.start()
    if (!payload) {
      fullscreen.then((granted) => granted && exitAppFullscreen())
      return
    }
    onStart(payload, fullscreen)
  }

  const blockedReason =
    activeCount === 0
      ? 'Add entries to this dictionary to see which cards can be made.'
      : setup.frontError || setup.backError
        ? 'Choose at least one field for each side to see eligible cards.'
        : setup.scopeEmpty
          ? 'Select at least one entry to see eligible cards.'
          : undefined

  return (
    <Dialog
      open={open}
      onClose={() => !setup.starting && onClose()}
      title="Train with cards"
      description={`${dictionary.title} · ${dictionary.sourceLanguage.name} → ${dictionary.targetLanguage.name}`}
      size="lg"
      dismissOnOverlayClick={!setup.starting}
      dismissOnEscape={!setup.starting}
      className="bg-background-elevated"
      footer={
        <DialogActions align="between" className="flex-wrap gap-2">
          <Button variant="secondary" onClick={onClose} disabled={setup.starting}>
            Cancel
          </Button>
          <Button
            onClick={handleStart}
            loading={setup.starting}
            disabled={!setup.canStart}
            leadingIcon={<PlayIcon className="h-4 w-4" />}
          >
            {setup.starting ? 'Preparing cards…' : 'Start'}
          </Button>
        </DialogActions>
      }
    >
      <div className="flex flex-col gap-6">
        {activeCount === 0 && (
          <InlineAlert tone="info" title="This dictionary has no active entries yet">
            Cards are made from active entries. Once entries are added, you can choose what appears
            on each side and start training.
          </InlineAlert>
        )}

        {!signedIn && (
          <InlineAlert tone="info" title="Session only">
            You're not signed in, so these choices and your ratings last only for this session.
          </InlineAlert>
        )}

        {setup.prefsStatus === 'error' && (
          <InlineAlert
            tone="warning"
            title="Couldn't load your saved settings"
            actions={
              <Button variant="secondary" size="compact" onClick={setup.retryPrefs}>
                Reload saved settings
              </Button>
            }
          >
            Showing default fields for now. Your choices are kept if you continue.
          </InlineAlert>
        )}

        {setup.conflict && (
          <InlineAlert
            tone="warning"
            title="Your saved settings changed on another device"
            actions={
              <div className="flex flex-wrap gap-2">
                <Button variant="secondary" size="compact" onClick={setup.reloadSaved} disabled={setup.conflictBusy}>
                  Reload saved settings
                </Button>
                <Button size="compact" onClick={setup.overwrite} loading={setup.conflictBusy}>
                  Overwrite with my choices
                </Button>
              </div>
            }
          >
            Saved now: Front {orderFields(setup.conflict.configuration.front).map((f) => FIELD_LABELS[f]).join(', ')}; Back{' '}
            {orderFields(setup.conflict.configuration.back).map((f) => FIELD_LABELS[f]).join(', ')};{' '}
            {setup.conflict.shuffle ? 'shuffled' : 'dictionary order'}. Your draft below hasn't been
            changed or saved.
          </InlineAlert>
        )}

        {setup.overwriteDone && (
          <InlineAlert tone="success" title="Your choices are saved">
            They replaced the settings from your other device.
          </InlineAlert>
        )}

        {setup.startError && (
          <InlineAlert
            tone="error"
            title={describeError(setup.startError).title}
            actions={
              <Button variant="secondary" size="compact" onClick={handleStart} disabled={!setup.canStart}>
                Try again
              </Button>
            }
          >
            {describeError(setup.startError).message} Your choices are kept.
          </InlineAlert>
        )}

        <section aria-labelledby="setup-sides" className="flex flex-col gap-3">
          <div>
            <h3 id="setup-sides" className="text-base font-semibold text-text-primary">
              Card sides
            </h3>
            <p className="text-sm text-text-secondary">
              Choose one or more fields for each side. Fields always appear in the order listed.
            </p>
          </div>
          <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
            <FieldGroup
              legend="Front"
              name="front"
              selected={setup.front}
              onChange={setup.setFront}
              error={setup.frontError}
              disabled={setup.starting || setup.prefsStatus === 'loading'}
            />
            <FieldGroup
              legend="Back"
              name="back"
              selected={setup.back}
              onChange={setup.setBack}
              error={setup.backError}
              disabled={setup.starting || setup.prefsStatus === 'loading'}
            />
          </div>
          {setup.identicalSides && (
            <InlineAlert tone="tip" title="Both sides show the same fields">
              You can still start, but flipping won't reveal anything new.
            </InlineAlert>
          )}
          <p className="flex gap-2 text-sm text-text-secondary">
            <InfoIcon className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
            <span>
              “Source-language” and “Target-language” mean the example's language, whichever column
              it's stored in. A missing or turned-off example falls back to the matching word.
              Other missing fields are left out; if a side ends up empty, that entry is skipped.
            </span>
          </p>
        </section>

        <RadioGroup
          label="Order"
          value={setup.shuffle ? 'shuffle' : 'dictionary'}
          onChange={(v) => setup.setShuffle(v === 'shuffle')}
          variant="card"
          orientation="horizontal"
          disabled={setup.starting}
        >
          <Radio value="shuffle" description="New order each round">
            Shuffle
          </Radio>
          <Radio value="dictionary" description="As listed in the dictionary">
            Dictionary order
          </Radio>
        </RadioGroup>

        <section aria-labelledby="setup-scope" className="flex flex-col gap-3">
          <h3 id="setup-scope" className="text-base font-semibold text-text-primary">
            Entries
          </h3>
          <RadioGroup
            label="Which entries"
            value={setup.scopeType}
            onChange={(v) => setup.setScopeType(v as 'all' | 'manual')}
            disabled={setup.starting || activeCount === 0}
          >
            <Radio
              value="all"
              description="Every active entry, regardless of the search or pages loaded in the editor."
            >
              All active entries ({activeCount})
            </Radio>
            <Radio value="manual" description="Advanced: pick specific entries for this session only.">
              Manual selection
            </Radio>
          </RadioGroup>
          {setup.scopeType === 'manual' && (
            <>
              <ManualSelection
                selectedIds={setup.manualIds}
                onToggle={setup.toggleManual}
                onSetMany={setup.setManualMany}
                onClear={setup.clearManual}
                sourceDir={dictionary.sourceLanguage.direction}
                targetDir={dictionary.targetLanguage.direction}
                sourceLang={dictionary.sourceLanguage.code}
                targetLang={dictionary.targetLanguage.code}
              />
              {setup.scopeEmpty && (
                <p role="alert" className="text-sm font-medium text-danger-default">
                  Select at least one entry to start.
                </p>
              )}
            </>
          )}
        </section>

        <section aria-labelledby="setup-summary" className="flex flex-col gap-3">
          <h3 id="setup-summary" className="text-base font-semibold text-text-primary">
            Ready to practise
          </h3>
          <PrepareSummary prepare={setup.prepare} onRetry={setup.retryPrepare} blockedReason={blockedReason} />
          <p className="text-sm text-text-tertiary">
            {signedIn
              ? 'Fields and order are remembered for this dictionary on all your devices. Entry selection resets each session.'
              : 'Sign in to remember these choices and save progress.'}
          </p>
        </section>
      </div>
    </Dialog>
  )
}

