import React from 'react'
import { ArrowLeftIcon, ArrowRightIcon } from 'lucide-react'
import type { Rating } from '../../../types/learning'
import { Spinner } from '../../Button'

interface SideRatingButtonProps {
  rating: Rating
  onRate: (rating: Rating) => void
  disabled: boolean
  loading: boolean
}

const COPY: Record<Rating, { label: string; key: string }> = {
  again: { label: 'Practise again', key: 'ArrowLeft' },
  known: { label: 'Known', key: 'ArrowRight' },
}

/** Quiet rating affordance beside the card (tablet/desktop). Hidden on mobile, where swipe is used. */
export function SideRatingButton({ rating, onRate, disabled, loading }: SideRatingButtonProps) {
  const Icon = rating === 'again' ? ArrowLeftIcon : ArrowRightIcon
  const { label, key } = COPY[rating]
  return (
    <button
      type="button"
      onClick={() => onRate(rating)}
      disabled={disabled}
      aria-keyshortcuts={key}
      aria-busy={loading || undefined}
      className={`hidden w-24 shrink-0 flex-col items-center justify-center gap-2 self-stretch rounded-2xl px-2 py-6 text-text-secondary transition-opacity duration-fast hover:bg-background-subtle hover:text-text-primary hover:opacity-100 focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-border-focus disabled:cursor-not-allowed md:flex ${
        loading ? 'opacity-100' : 'opacity-30'
      }`}
    >
      <span className="flex h-12 w-12 items-center justify-center rounded-full border border-border-strong bg-background-surface">
        {loading ? <Spinner /> : <Icon className="h-5 w-5" aria-hidden />}
      </span>
      <span className="text-center text-sm font-medium">{label}</span>
    </button>
  )
}

