import { useEffect } from 'react'
import { toast } from 'sonner'
import { useCountdown } from '../../../hooks/useCountdown'
import { RATING_LABEL } from './usePracticeSession'
import type { Pending } from './usePracticeSession'

const TOAST_ID = 'flashcard-save-error'

/** Save/undo failures surface only as a persistent toast with Retry (same operation ID). */
export function useSaveErrorToast(pending: Pending | null, onRetry: () => void) {
  const wait = useCountdown(pending?.retryAt)

  useEffect(() => {
    if (pending?.status !== 'error' || !pending.error) {
      toast.dismiss(TOAST_ID)
      return
    }
    const isUndo = pending.kind === 'undo'
    const label = RATING_LABEL[pending.rating]
    const description =
      pending.error.code === 'rate_limited'
        ? `Too many requests. ${wait > 0 ? `You can retry in ${wait}s.` : 'You can retry now.'}`
        : isUndo
          ? "We couldn't confirm the undo. Retrying is safe — it won't apply twice."
          : `We couldn't confirm “${label}” was saved. Retrying is safe and won't count it twice.`
    toast.error(isUndo ? 'Undo not confirmed' : 'Rating not saved', {
      id: TOAST_ID,
      description,
      duration: Infinity,
      action: {
        label: wait > 0 ? `Retry in ${wait}s` : 'Retry',
        onClick: (event) => {
          event.preventDefault()
          onRetry()
        },
      },
    })
  }, [pending, wait, onRetry])

  useEffect(() => () => void toast.dismiss(TOAST_ID), [])
}

