import React, { createContext, useContext, useEffect, useMemo, useState } from 'react'
import type { DemoState } from '../types/demo'
import { setMockContext } from '../utils/mockLearningApi'

interface DemoContextValue extends DemoState {
  update: (patch: Partial<DemoState>) => void
  /** Changes whenever the learner identity or share key changes; ends any session. */
  identity: string
}

const DemoContext = createContext<DemoContextValue | null>(null)

export function DemoProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<DemoState>({
    role: 'owner',
    learner: 'A',
    theme: 'light',
    dictionaryKey: 'spanish',
    scenario: 'normal',
    shareKeyVersion: 1,
  })

  // Keep the mock adapter in sync before children effects issue requests.
  setMockContext({
    role: state.role,
    learner: state.learner,
    dictionaryKey: state.dictionaryKey,
    scenario: state.scenario,
    shareKeyVersion: state.shareKeyVersion,
  })

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', state.theme)
  }, [state.theme])

  const value = useMemo<DemoContextValue>(
    () => ({
      ...state,
      update: (patch) => setState((prev) => ({ ...prev, ...patch })),
      identity: [
        state.role,
        state.role === 'anonymous' ? '-' : state.learner,
        state.role === 'owner' ? '-' : state.shareKeyVersion,
        state.dictionaryKey,
      ].join('|'),
    }),
    [state],
  )

  return <DemoContext.Provider value={value}>{children}</DemoContext.Provider>
}

export function useDemo(): DemoContextValue {
  const ctx = useContext(DemoContext)
  if (!ctx) throw new Error('useDemo must be used inside DemoProvider')
  return ctx
}

