import React, { useEffect, useRef, useState } from 'react'
import { InfoIcon, Undo2Icon } from 'lucide-react'
import { useFocusTrap } from '../../../hooks/useFocusTrap'
import type { DictionaryRecord } from '../../../types/dictionary'
import type { Scenario } from '../../../types/demo'
import { Button } from '../../Button'
import { InlineAlert } from '../../InlineAlert'
import { Skeleton } from '../../Skeleton'
import type { StartPayload } from '../SetupDialog/useFlashcardSetup'
import { ConflictNotice } from './ConflictNotice'
import { EndSessionDialog } from './EndSessionDialog'
import { Flashcard } from './Flashcard'
import { ResultsPanel } from './ResultsPanel'
import { SessionHeader } from './SessionHeader'
import { SessionStatusScreen } from './SessionStatusScreen'
import { SideRatingButton } from './SideRatingButton'
import { useDisplayMode } from './useDisplayMode'
import { usePracticeSession } from './usePracticeSession'
import { useSaveErrorToast } from './useSaveErrorToast'

interface PracticeSessionProps {
  sessionId: string
  dictionary: DictionaryRecord
  payload: StartPayload
  signedIn: boolean
  scenario: Scenario
  identity: string
  fullscreenRequest: Promise<boolean>
  onClose: () => void
  onForcedEnd: (savedCount: number) => void
}

export function PracticeSession(props: PracticeSessionProps) {
  const { dictionary, payload, signedIn } = props
  const session = usePracticeSession({
    sessionId: props.sessionId,
    configuration: payload.configuration,
    shuffle: payload.shuffle,
    entryIds: payload.entryIds,
    signedIn,
  })
  const { state } = session
  const display = useDisplayMode(props.fullscreenRequest, props.scenario === 'fullscreenRejected')
  const [endOpen, setEndOpen] = useState(false)
  const containerRef = useRef<HTMLElement>(null)
  const titleRef = useRef<HTMLHeadingElement>(null)

  useFocusTrap(containerRef, !endOpen, titleRef)
  useSaveErrorToast(state.pending, session.retry)

  useEffect(() => {
    const previous = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.body.style.overflow = previous
    }
  }, [])

  // Signing out, changing learner or changing share key ends the session.
  const identityRef = useRef(props.identity)
  const savedRef = useRef(state.savedCount)
  savedRef.current = state.savedCount
  const { identity, onForcedEnd } = props
  useEffect(() => {
    if (identity !== identityRef.current) onForcedEnd(savedRef.current)
  }, [identity, onForcedEnd])

  const { rate, flip } = session
  const { mode, toDialog } = display
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (endOpen) return
      const target = event.target as HTMLElement
      if (event.key === 'Escape') {
        event.preventDefault()
        // Overlay simulates fullscreen: Escape leaves it for dialog view, never End.
        if (mode === 'overlay') toDialog()
        else if (mode === 'dialog') setEndOpen(true)
        return
      }
      if (target.closest('input, textarea, select')) return
      if (event.key === 'ArrowLeft') {
        event.preventDefault()
        rate('again')
      } else if (event.key === 'ArrowRight') {
        event.preventDefault()
        rate('known')
      } else if ((event.key === 'Enter' || event.key === ' ') && !target.closest('button, a, [role="menuitem"]')) {
        event.preventDefault()
        flip()
      }
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [endOpen, mode, toDialog, rate, flip])

  const total = state.queue.length
  const subtitle =
    state.phase === 'card'
      ? `Round ${state.round} · Card ${Math.min(state.index + 1, total)} of ${total}`
      : state.phase === 'results'
        ? `Round ${state.round} · Results`
        : state.phase === 'loading'
          ? 'Preparing your cards…'
          : 'Practice paused'

  const ratingBlocked = Boolean(state.pending) || Boolean(state.conflict) || !session.currentItem
  const savingRating =
    state.pending?.kind === 'rate' && state.pending.status === 'saving' ? state.pending.rating : undefined
  const inDialog = mode === 'dialog'
  const cardPhase = state.phase === 'card'

  const undoButton =
    state.lastAck && !state.pending ? (
      <Button variant="ghost" leadingIcon={<Undo2Icon className="h-4 w-4" />} onClick={session.undo}>
        Undo last rating
      </Button>
    ) : state.pending?.kind === 'undo' ? (
      <Button variant="ghost" loading disabled>
        Undoing…
      </Button>
    ) : null

  return (
    <div
      className={
        inDialog
          ? 'fixed inset-0 z-40 flex items-center justify-center bg-overlay p-4'
          : 'fixed inset-0 z-40 flex bg-background-canvas'
      }
    >
      <section
        ref={containerRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="practice-title"
        className={
          inDialog
            ? 'dialog-frame flex max-w-4xl flex-col overflow-hidden rounded-3xl border border-border-default bg-background-elevated shadow-elev-lg'
            : 'viewport-fill flex w-full flex-col overflow-hidden'
        }
      >
        <SessionHeader
          titleRef={titleRef}
          dictionaryTitle={dictionary.title}
          subtitle={subtitle}
          mode={mode}
          progressValue={state.roundStats.reviewed}
          progressMax={total}
          showProgress={state.phase === 'card'}
          onToDialog={toDialog}
          onToFullscreen={display.toFullscreen}
          onEnd={() => setEndOpen(true)}
        />
        {!signedIn && (
          <p className="flex items-center gap-2 border-b border-border-default bg-background-subtle px-4 py-2 text-sm text-text-secondary md:px-6">
            <InfoIcon className="h-4 w-4 shrink-0" aria-hidden />
            Session only — ratings aren't saved, and signing in won't import them.
          </p>
        )}

        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
          <div
            className={`pb-safe mx-auto flex w-full max-w-4xl flex-col gap-4 px-4 pt-6 md:px-6 md:pt-8 ${
              cardPhase ? 'h-full' : 'min-h-full'
            }`}
          >
            {display.notice && (
              <InlineAlert tone="info" onDismiss={display.dismissNotice} dismissLabel="Dismiss fullscreen notice">
                {display.notice}
              </InlineAlert>
            )}
            {state.notices.map((notice, i) => (
              <InlineAlert key={`${notice}-${i}`} tone="info" title="Card skipped" onDismiss={() => session.dismissNotice(i)}>
                {notice}
              </InlineAlert>
            ))}
            {state.conflict && (state.phase === 'card' || state.phase === 'results') && (
              <ConflictNotice
                kind={state.conflict}
                busy={state.conflictBusy}
                onReloadCard={session.resolveContentConflict}
                onDismiss={session.dismissConflict}
              />
            )}

            {state.phase === 'loading' && <CardSkeleton label="Preparing your cards…" />}

            {cardPhase && (
              <>
                <div dir="ltr" className="flex min-h-0 flex-1 items-center gap-2 lg:gap-4">
                  <SideRatingButton
                    rating="again"
                    onRate={rate}
                    disabled={ratingBlocked}
                    loading={savingRating === 'again'}
                  />
                  <div className="mx-auto flex h-full min-h-0 w-full min-w-0 max-w-2xl flex-1 items-center">
                    {session.currentItem ? (
                      <Flashcard
                        item={session.currentItem}
                        face={state.face}
                        position={`${state.index + 1} / ${total}`}
                        onFlip={flip}
                        onRate={rate}
                        ratingDisabled={ratingBlocked}
                        flipDisabled={state.pending?.status === 'saving'}
                      />
                    ) : (
                      <div className="w-full">
                        <CardSkeleton label="Loading the next cards…" />
                      </div>
                    )}
                  </div>
                  <SideRatingButton
                    rating="known"
                    onRate={rate}
                    disabled={ratingBlocked}
                    loading={savingRating === 'known'}
                  />
                </div>
                <div className="flex min-h-11 shrink-0 items-center justify-center">{undoButton}</div>
              </>
            )}

            {state.phase === 'results' && (
              <ResultsPanel
                round={state.round}
                roundStats={state.roundStats}
                outcomes={state.outcomes}
                reviewEvents={state.reviewEvents}
                roundsCompleted={state.roundsCompleted}
                signedIn={signedIn}
                dictionaryTitle={dictionary.title}
                progress={state.progress}
                progressStatus={state.progressStatus}
                onRetryProgress={session.refreshProgress}
                onPractiseAgain={session.practiseAgain}
                onStartOver={session.startOver}
                onFinish={props.onClose}
                actionsDisabled={Boolean(state.pending)}
                undoSlot={undoButton && <div>{undoButton}</div>}
              />
            )}

            {state.phase === 'error' && (
              <SessionStatusScreen
                variant="error"
                error={state.error}
                retryAt={state.errorRetryAt}
                savedCount={state.savedCount}
                signedIn={signedIn}
                onRetry={session.retryLoad}
                onExit={props.onClose}
              />
            )}

            {state.phase === 'unavailable' && (
              <SessionStatusScreen
                variant="unavailable"
                savedCount={state.savedCount}
                signedIn={signedIn}
                onExit={props.onClose}
              />
            )}
          </div>
        </div>

      </section>

      <div className="sr-only" aria-live="polite" aria-atomic="true">
        {state.announcement}
      </div>

      <EndSessionDialog
        open={endOpen}
        signedIn={signedIn}
        savingInProgress={state.pending?.status === 'saving'}
        onKeep={() => setEndOpen(false)}
        onEnd={props.onClose}
      />
    </div>
  )
}

function CardSkeleton({ label }: { label: string }) {
  return (
    <div className="flex flex-col gap-3">
      <div className="rounded-3xl border border-border-default bg-background-surface p-6 shadow-elev-sm">
        <Skeleton width="30%" />
        <div className="mt-8">
          <Skeleton lines={3} />
        </div>
      </div>
      <p className="text-center text-sm text-text-secondary">{label}</p>
    </div>
  )
}

