import React from 'react'
import type { Field } from '../../../types/learning'
import { FIELD_LABELS, FIELD_ORDER, orderFields } from '../../../utils/flashcardFields'
import { Checkbox } from '../../Checkbox'

interface FieldGroupProps {
  legend: string
  name: string
  selected: Field[]
  onChange: (fields: Field[]) => void
  error?: string
  disabled?: boolean
}

export function FieldGroup({ legend, name, selected, onChange, error, disabled }: FieldGroupProps) {
  const errorId = `${name}-error`
  const ordered = orderFields(selected)

  const toggle = (field: Field) => {
    onChange(selected.includes(field) ? selected.filter((f) => f !== field) : [...selected, field])
  }

  return (
    <fieldset
      className="min-w-0 rounded-2xl border border-border-default bg-background-surface p-4"
      aria-describedby={error ? errorId : undefined}
      disabled={disabled}
    >
      <legend className="px-1 text-base font-semibold text-text-primary">{legend}</legend>
      <div className="mt-2 flex flex-col gap-1">
        {FIELD_ORDER.map((field) => (
          <Checkbox
            key={field}
            name={name}
            value={field}
            label={FIELD_LABELS[field]}
            checked={selected.includes(field)}
            onChange={() => toggle(field)}
          />
        ))}
      </div>
      <p className="mt-3 text-sm text-text-secondary">
        {ordered.length > 0 ? (
          <>
            <span className="text-text-tertiary">Shown in order: </span>
            {ordered.map((f) => FIELD_LABELS[f]).join(' · ')}
          </>
        ) : null}
      </p>
      {error && (
        <p id={errorId} role="alert" className="mt-2 text-sm font-medium text-danger-default">
          {error}
        </p>
      )}
    </fieldset>
  )
}

