import React from 'react'
import { CheckCircle2Icon, CornerDownRightIcon, MinusCircleIcon } from 'lucide-react'
import { describeError } from '../../../utils/apiError'
import { Button } from '../../Button'
import { InlineAlert } from '../../InlineAlert'
import { Skeleton } from '../../Skeleton'
import type { PrepareState } from './useFlashcardSetup'

interface PrepareSummaryProps {
  prepare: PrepareState
  onRetry: () => void
  blockedReason?: string
}

export function PrepareSummary({ prepare, onRetry, blockedReason }: PrepareSummaryProps) {
  if (blockedReason) {
    return <p className="text-sm text-text-secondary">{blockedReason}</p>
  }
  if (prepare.status === 'error' && prepare.error) {
    const copy = describeError(prepare.error)
    return (
      <InlineAlert
        tone="error"
        title="Couldn't check which cards can be made"
        actions={
          <Button variant="secondary" size="compact" onClick={onRetry}>
            Retry
          </Button>
        }
      >
        {copy.message}
      </InlineAlert>
    )
  }
  if (prepare.status !== 'ready' || !prepare.result) {
    return (
      <div className="grid grid-cols-3 gap-3" aria-label="Checking eligible cards">
        {[0, 1, 2].map((i) => (
          <Skeleton key={i} variant="rect" height={72} />
        ))}
      </div>
    )
  }
  const { eligibleCount, skippedCount, fallbackCount } = prepare.result
  const stats = [
    { label: 'Eligible', value: eligibleCount, icon: CheckCircle2Icon, note: 'cards ready' },
    { label: 'Skipped', value: skippedCount, icon: MinusCircleIcon, note: 'empty side' },
    { label: 'With fallback', value: fallbackCount, icon: CornerDownRightIcon, note: 'entries' },
  ]
  return (
    <div className="flex flex-col gap-3">
      <dl className="grid grid-cols-3 gap-2 sm:gap-3" aria-live="polite">
        {stats.map(({ label, value, icon: Icon, note }) => (
          <div
            key={label}
            className="min-w-0 rounded-xl border border-border-default bg-background-subtle px-3 py-3"
          >
            <dt className="flex items-center gap-1 text-xs font-medium text-text-secondary">
              <Icon className="h-4 w-4 shrink-0" aria-hidden />
              <span className="truncate">{label}</span>
            </dt>
            <dd className="mt-1 text-2xl font-semibold tabular-nums text-text-primary">{value}</dd>
            <dd className="text-xs text-text-tertiary">{note}</dd>
          </div>
        ))}
      </dl>
      {eligibleCount === 0 && (
        <InlineAlert tone="warning" title="No cards can be made with these fields">
          Every selected entry would have an empty front or back. Choose fields these entries
