import React, { useEffect, useState } from 'react'
import { ChevronLeftIcon, ChevronRightIcon, SearchIcon } from 'lucide-react'
import type { Direction, EntryPreview } from '../../../types/learning'
import { ApiError, describeError, toApiError } from '../../../utils/apiError'
import { learningApi } from '../../../utils/mockLearningApi'
import { Button } from '../../Button'
import { Checkbox } from '../../Checkbox'
import { InlineAlert } from '../../InlineAlert'
import { Input } from '../../Input'
import { Skeleton } from '../../Skeleton'

interface ManualSelectionProps {
  selectedIds: Set<string>
  onToggle: (entryId: string) => void
  onSetMany: (ids: string[], selected: boolean) => void
  onClear: () => void
  sourceDir: Direction
  targetDir: Direction
  sourceLang: string
  targetLang: string
}

export function ManualSelection(props: ManualSelectionProps) {
  const { selectedIds, onToggle, onSetMany, onClear } = props
  const [search, setSearch] = useState('')
  const [query, setQuery] = useState('')
  const [cursors, setCursors] = useState<(string | null)[]>([null])
  const [entries, setEntries] = useState<EntryPreview[]>([])
  const [nextCursor, setNextCursor] = useState<string | null>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [error, setError] = useState<ApiError | null>(null)
  const [attempt, setAttempt] = useState(0)
  const pageCursor = cursors[cursors.length - 1]

  useEffect(() => {
    const t = window.setTimeout(() => {
      setQuery(search)
      setCursors([null])
    }, 300)
    return () => window.clearTimeout(t)
  }, [search])

  useEffect(() => {
    let cancelled = false
    setStatus('loading')
    learningApi
      .listEntries(query, pageCursor)
      .then((page) => {
        if (cancelled) return
        setEntries(page.entries)
        setNextCursor(page.nextCursor)
        setStatus('ready')
      })
      .catch((e) => {
        if (cancelled) return
        setError(toApiError(e))
        setStatus('error')
      })
    return () => {
      cancelled = true
    }
  }, [query, pageCursor, attempt])

  const pageIds = entries.map((e) => e.entryId)
  const allOnPage = pageIds.length > 0 && pageIds.every((id) => selectedIds.has(id))
  const someOnPage = pageIds.some((id) => selectedIds.has(id))
  const pageNumber = cursors.length

  return (
    <div className="flex flex-col gap-3 rounded-2xl border border-border-default bg-background-surface p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm font-medium text-text-primary" aria-live="polite">
          {selectedIds.size} selected
        </p>
        <Button variant="ghost" size="compact" onClick={onClear} disabled={selectedIds.size === 0}>
          Clear selection
        </Button>
      </div>
      <Input
        label="Search entries"
        type="search"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        placeholder="Search source or translation"
        leadingIcon={<SearchIcon className="h-4 w-4" />}
        hint="Selections are kept when you search or change pages."
      />

      {status === 'error' && error ? (
        <InlineAlert
          tone="error"
          title="Couldn't load entries"
          actions={
            <Button variant="secondary" size="compact" onClick={() => setAttempt((n) => n + 1)}>
              Retry
            </Button>
          }
        >
          {describeError(error).message}
        </InlineAlert>
      ) : status === 'loading' ? (
        <Skeleton lines={6} />
      ) : entries.length === 0 ? (
        <p className="py-4 text-center text-sm text-text-secondary">No entries match “{query}”.</p>
      ) : (
        <>
          <Checkbox
            label={`Select all on this page (${entries.length})`}
            checked={allOnPage}
            indeterminate={!allOnPage && someOnPage}
            onChange={() => onSetMany(pageIds, !allOnPage)}
          />
          <ul className="flex flex-col divide-y divide-border-default rounded-xl border border-border-default">
            {entries.map((entry) => (
              <li key={entry.entryId} className="px-3 py-1">
                <Checkbox
                  checked={selectedIds.has(entry.entryId)}
                  onChange={() => onToggle(entry.entryId)}
                  label={
                    <span className="grid min-w-0 grid-cols-2 gap-3">
                      <span lang={props.sourceLang} dir={props.sourceDir} className="truncate text-text-primary">
                        {entry.source}
                      </span>
                      <span lang={props.targetLang} dir={props.targetDir} className="truncate text-text-secondary">
                        {entry.translation}
                      </span>
                    </span>
                  }
                />
              </li>
            ))}
          </ul>
        </>
      )}

      <nav aria-label="Entry pages" className="flex items-center justify-between gap-2">
        <Button
          variant="secondary"
          size="compact"
          leadingIcon={<ChevronLeftIcon className="h-4 w-4" />}
          disabled={cursors.length <= 1 || status === 'loading'}
          onClick={() => setCursors((c) => c.slice(0, -1))}
        >
          Previous
        </Button>
        <span className="text-sm text-text-secondary">Page {pageNumber}</span>
        <Button
          variant="secondary"
          size="compact"
          trailingIcon={<ChevronRightIcon className="h-4 w-4" />}
          disabled={!nextCursor || status === 'loading'}
          onClick={() => setCursors((c) => [...c, nextCursor])}
        >
          Next
        </Button>
      </nav>
    </div>
  )
}

