import React, { useRef, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { ArrowLeftIcon, ArrowRightIcon, CornerDownRightIcon, RefreshCwIcon } from 'lucide-react'
import type { Face, FlashcardItem, Presentation, Rating } from '../../../types/learning'
import { FIELD_LABELS, fallbackNote, languageName } from '../../../utils/flashcardFields'
import { Badge } from '../../Badge'
import { Button } from '../../Button'

interface FlashcardProps {
  item: FlashcardItem
  face: Face
  position: string
  onFlip: () => void
  onRate: (rating: Rating) => void
  ratingDisabled: boolean
  flipDisabled: boolean
}

interface DragState {
  x: number
  y: number
  id: number
  axis: 'x' | 'y' | null
  pointerType: string
  onText: boolean
}

const INTENT_PX = 10

export function Flashcard({ item, face, position, onFlip, onRate, ratingDisabled, flipDisabled }: FlashcardProps) {
  const reduceMotion = useReducedMotion()
  const cardRef = useRef<HTMLDivElement>(null)
  const drag = useRef<DragState | null>(null)
  const moved = useRef(false)
  const clickTimer = useRef<number>()
  const thresholdRef = useRef(100)
  const dxRef = useRef(0)
  const [dx, setDx] = useState(0)

  const setOffset = (value: number) => {
    dxRef.current = value
    setDx(value)
  }

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    const target = e.target as HTMLElement
    moved.current = false
    if (e.button !== 0 || target.closest('button')) return
    drag.current = {
      x: e.clientX,
      y: e.clientY,
      id: e.pointerId,
      axis: null,
      pointerType: e.pointerType,
      onText: Boolean(target.closest('[data-card-text]')),
    }
    thresholdRef.current = Math.min(120, (cardRef.current?.offsetWidth ?? 320) * 0.3)
  }

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d || d.id !== e.pointerId) return
    const ddx = e.clientX - d.x
    const ddy = e.clientY - d.y
    if (d.axis === null) {
      if (Math.abs(ddx) > INTENT_PX && Math.abs(ddx) > Math.abs(ddy) * 1.2) {
        moved.current = true
        // Mouse drags that start on text are text selection, not swipes.
        if (ratingDisabled || (d.pointerType === 'mouse' && d.onText)) {
          d.axis = 'y'
          return
        }
        d.axis = 'x'
        cardRef.current?.setPointerCapture(e.pointerId)
      } else if (Math.abs(ddy) > INTENT_PX) {
        moved.current = true
        d.axis = 'y'
        return
      } else return
    }
    if (d.axis === 'x') setOffset(ddx)
  }

  const endDrag = (commit: boolean) => {
    const d = drag.current
    drag.current = null
    if (!d || d.axis !== 'x') return
    const offset = dxRef.current
    setOffset(0)
    if (commit && Math.abs(offset) >= thresholdRef.current) onRate(offset > 0 ? 'known' : 'again')
  }

  const onClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (moved.current || (e.target as HTMLElement).closest('button')) return
    if (e.detail > 1) {
      window.clearTimeout(clickTimer.current)
      return
    }
    clickTimer.current = window.setTimeout(() => {
      if (!window.getSelection()?.toString()) onFlip()
    }, 220)
  }

  const progress = Math.min(1, Math.abs(dx) / thresholdRef.current)
  const committed = progress >= 1
  const presentations = face === 'front' ? item.front : item.back
  const dragging = dx !== 0

  return (
    <div className="relative flex max-h-full min-h-0 w-full flex-col">
      <div
        ref={cardRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={() => endDrag(true)}
        onPointerCancel={() => endDrag(false)}
        onClick={onClick}
        className={`relative flex min-h-0 touch-pan-y select-text flex-col overflow-hidden rounded-3xl border bg-background-surface shadow-elev-md ${
          committed ? 'border-border-focus' : 'border-border-default'
        } ${dragging ? '' : 'transition-transform duration-normal'}`}
        style={{
          transform: dragging ? `translateX(${dx}px) rotate(${reduceMotion ? 0 : dx / 40}deg)` : undefined,
        }}
      >
        <div className="flex shrink-0 items-center justify-between gap-2 border-b border-border-default px-4 py-3 md:px-6">
          <Badge tone={face === 'front' ? 'info' : 'neutral'} withDot>
            {face === 'front' ? 'Front' : 'Back'}
          </Badge>
          <span className="text-sm text-text-tertiary">{position}</span>
        </div>

        <AnimatePresence mode="wait" initial={false}>
          <motion.div
            key={`${item.entryId}-${face}-${item.learningVersion}`}
            initial={{ opacity: 0, y: reduceMotion ? 0 : 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: reduceMotion ? 0 : 0.2 }}
            tabIndex={0}
            aria-label={`${face === 'front' ? 'Front' : 'Back'} of card ${position}`}
            className="min-h-40 flex-1 cursor-pointer overflow-y-auto overscroll-contain px-5 py-8 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus md:px-10 md:py-12"
          >
            <dl className="flex flex-col gap-6">
              {presentations.map((p) => (
                <CardField key={p.field} presentation={p} />
              ))}
            </dl>
          </motion.div>
        </AnimatePresence>

        <div className="shrink-0 border-t border-border-default p-2">
          <Button
            variant="ghost"
            fullWidth
            onClick={onFlip}
            disabled={flipDisabled}
            leadingIcon={<RefreshCwIcon className="h-4 w-4" />}
            aria-keyshortcuts="Enter Space"
          >
            {face === 'front' ? 'Show back' : 'Show front'}
          </Button>
        </div>

        {dragging && (
          <div aria-hidden className="pointer-events-none absolute inset-x-0 top-14 flex flex-col items-center gap-2 px-4">
            <div dir="ltr" className="flex w-full justify-between">
              <SwipeHint visible={dx < 0} committed={committed && dx < 0} side="left" />
              <SwipeHint visible={dx > 0} committed={committed && dx > 0} side="right" />
            </div>
            <div className="h-1 w-32 overflow-hidden rounded-full bg-background-subtle">
              <div className="h-full rounded-full bg-primary-default" style={{ width: `${progress * 100}%` }} />
            </div>
            <p className="rounded-full bg-background-elevated px-2 text-xs text-text-secondary">
              {committed ? 'Release to rate · drag back to cancel' : 'Keep dragging to rate'}
            </p>
          </div>
        )}
      </div>
    </div>
  )
}

function CardField({ presentation: p }: { presentation: Presentation }) {
  const note = fallbackNote(p)
  const isWord = p.field === 'source' || p.field === 'translation'
  const long = p.text.length > 160
  const textClass = isWord
    ? 'text-3xl font-semibold md:text-4xl'
    : p.field === 'transcription'
      ? 'text-lg text-text-secondary'
      : long
        ? 'text-base leading-relaxed md:text-lg'
        : 'text-xl md:text-2xl'
  return (
    <div className="min-w-0">
      <dt className="text-xs font-medium uppercase tracking-wide text-text-tertiary">
        {FIELD_LABELS[p.field]} · {languageName(p.language)}
      </dt>
      <dd
        lang={p.language}
        dir={p.direction}
        data-card-text
        className={`mt-1 whitespace-pre-line break-words text-start text-text-primary ${textClass}`}
      >
        {p.text}
      </dd>
      {note && (
        <dd className="mt-2 flex items-start gap-2 text-sm text-text-secondary">
          <CornerDownRightIcon className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
          <span>{note}</span>
        </dd>
      )}
    </div>
  )
}

function SwipeHint({ visible, committed, side }: { visible: boolean; committed: boolean; side: 'left' | 'right' }) {
  const Icon = side === 'left' ? ArrowLeftIcon : ArrowRightIcon
  return (
    <span
      className={`inline-flex items-center gap-2 rounded-full border px-3 py-1 text-sm font-medium transition-opacity duration-fast ${
        visible ? 'opacity-100' : 'opacity-0'
      } ${
        committed
          ? 'border-primary-default bg-primary-default text-on-primary'
          : 'border-border-strong bg-background-elevated text-text-primary'
      }`}
    >
      {side === 'left' && <Icon className="h-4 w-4" />}
      {side === 'left' ? 'Practise again' : 'Known'}
      {side === 'right' && <Icon className="h-4 w-4" />}
    </span>
  )
}

