import React from 'react'
import { Button } from '../../Button'
import { InlineAlert } from '../../InlineAlert'
import type { ConflictKind } from './usePracticeSession'

interface ConflictNoticeProps {
  kind: ConflictKind
  busy: boolean
  onReloadCard: () => void
  onDismiss: () => void
}

export function ConflictNotice({ kind, busy, onReloadCard, onDismiss }: ConflictNoticeProps) {
  if (kind === 'content') {
    return (
      <InlineAlert
        tone="warning"
        title="This card was updated"
        actions={
          <Button size="compact" onClick={onReloadCard} loading={busy}>
            Load updated card
          </Button>
        }
      >
        The entry was edited after it was shown, so your rating wasn't saved. Load the latest
        version and rate it again. Edited entries count as unstudied in saved progress.
      </InlineAlert>
    )
  }
  if (kind === 'operation') {
    return (
      <InlineAlert
        tone="warning"
        title="That rating couldn't be confirmed"
        actions={
          <Button size="compact" onClick={onDismiss}>
            Rate this card again
          </Button>
        }
      >
        Languon received a different request with the same reference, so nothing was overwritten.
        Your saved progress has been refreshed.
      </InlineAlert>
    )
  }
  return (
    <InlineAlert
      tone="warning"
      title="Undo isn't available anymore"
      actions={
        <Button variant="secondary" size="compact" onClick={onDismiss}>
          OK
        </Button>
      }
    >
      A newer rating for this entry was saved — possibly on another device — so it wasn't
      overwritten. Your saved progress has been refreshed.
    </InlineAlert>
  )
}

