import React from 'react'
import { AlertTriangleIcon, LockIcon } from 'lucide-react'
import { useCountdown } from '../../../hooks/useCountdown'
import { ApiError, describeError } from '../../../utils/apiError'
import { Button } from '../../Button'

interface SessionStatusScreenProps {
  variant: 'error' | 'unavailable'
  error?: ApiError | null
  retryAt?: number
  savedCount: number
  signedIn: boolean
  onRetry?: () => void
  onExit: () => void
}

export function SessionStatusScreen({ variant, error, retryAt, savedCount, signedIn, onRetry, onExit }: SessionStatusScreenProps) {
  const wait = useCountdown(retryAt)
  const copy =
    variant === 'unavailable'
      ? {
          title: "This dictionary isn't available anymore",
          message:
            'Access may have been removed, or the dictionary was archived. Practice content has been cleared from this screen.',
        }
      : error
        ? describeError(error)
        : { title: 'Something went wrong', message: 'Try again.' }
  const Icon = variant === 'unavailable' ? LockIcon : AlertTriangleIcon

  return (
    <div className="mx-auto flex max-w-md flex-col items-center gap-4 py-12 text-center" role="alert">
      <span className="flex h-12 w-12 items-center justify-center rounded-full bg-background-subtle text-text-secondary">
        <Icon className="h-6 w-6" aria-hidden />
      </span>
      <h3 className="text-xl font-semibold text-text-primary">{copy.title}</h3>
      <p className="text-text-secondary">{copy.message}</p>
      {signedIn && savedCount > 0 && (
        <p className="text-sm text-text-secondary">
          {savedCount} {savedCount === 1 ? 'rating was' : 'ratings were'} saved before this and stay saved.
        </p>
      )}
      <div className="flex flex-wrap justify-center gap-3">
        {variant === 'error' && onRetry && (
          <Button onClick={onRetry} disabled={wait > 0}>
            {wait > 0 ? `Retry in ${wait}s` : 'Retry'}
          </Button>
        )}
        <Button variant="secondary" onClick={onExit}>
          {variant === 'unavailable' ? 'Close' : 'End session'}
        </Button>
      </div>
    </div>
  )
}

