import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { CopyIcon, LogInIcon, MoreHorizontalIcon, PlusIcon, SearchIcon, SettingsIcon } from 'lucide-react'
import { toast } from 'sonner'
import { useDemo } from '../../contexts/DemoContext'
import { useCapabilities } from '../../hooks/useCapabilities'
import { useMockRevision } from '../../hooks/useMockStore'
import type { DictionaryKey } from '../../types/dictionary'
import type { Role } from '../../types/demo'
import { getWorkspaceDictionary, newId } from '../../utils/mockLearningApi'
import { Button } from '../Button'
import { IconButton } from '../IconButton'
import { InlineAlert } from '../InlineAlert'
import { Input } from '../Input'
import { PracticeSession } from '../training/PracticeSession/PracticeSession'
import { SetupDialog } from '../training/SetupDialog/SetupDialog'
import type { StartPayload } from '../training/SetupDialog/useFlashcardSetup'
import { TrainMenu } from '../training/TrainMenu'
import { DictionaryHeader } from './DictionaryHeader'
import { EntryCard } from './EntryCard'

interface ActiveSession {
  id: string
  payload: StartPayload
  fullscreen: Promise<boolean>
  role: Role
  learner: string
  shareKeyVersion: number
  dictionaryKey: DictionaryKey
  signedIn: boolean
}

const PAGE = 12

export function DictionaryWorkspace() {
  const demo = useDemo()
  useMockRevision()
  const dictionary = getWorkspaceDictionary()
  const active = dictionary.entries.filter((e) => !e.archived)
  const capability = useCapabilities(`${demo.scenario}|${demo.identity}`)
  const isOwner = demo.role === 'owner'
  const signedIn = demo.role !== 'anonymous'

  const [setupOpen, setSetupOpen] = useState(false)
  const [session, setSession] = useState<ActiveSession | null>(null)
  const [endNotice, setEndNotice] = useState<string | null>(null)
  const [search, setSearch] = useState('')
  const [visible, setVisible] = useState(PAGE)
  const ownerTrainRef = useRef<HTMLDivElement>(null)
  const readerTrainRef = useRef<HTMLDivElement>(null)

  const focusTrain = useCallback(() => {
    window.requestAnimationFrame(() => {
      const wrapper = ownerTrainRef.current ?? readerTrainRef.current
      wrapper?.querySelector<HTMLButtonElement>('button')?.focus()
    })
  }, [])

  useEffect(() => {
    setSetupOpen(false)
  }, [demo.identity])

  const filtered = useMemo(() => {
    const needle = search.trim().toLocaleLowerCase()
    return needle
      ? active.filter(
          (e) => e.source.toLocaleLowerCase().includes(needle) || e.translation.toLocaleLowerCase().includes(needle),
        )
      : active
  }, [active, search])

  const unchanged = () => toast('Authoring is unchanged and not part of the training prototype.')

  const handleStart = (payload: StartPayload, fullscreen: Promise<boolean>) => {
    setSetupOpen(false)
    setEndNotice(null)
    setSession({
      id: newId(),
      payload,
      fullscreen,
      role: demo.role,
      learner: demo.learner,
      shareKeyVersion: demo.shareKeyVersion,
      dictionaryKey: demo.dictionaryKey,
      signedIn,
    })
  }

  const closeSession = useCallback(() => {
    setSession(null)
    focusTrain()
  }, [focusTrain])

  const handleForcedEnd = useCallback(
    (savedCount: number) => {
      if (!session) return
      const saved =
        savedCount > 0
          ? ` ${savedCount} ${savedCount === 1 ? 'rating was' : 'ratings were'} already saved and stay saved.`
          : ''
      let message: string
      if (!session.signedIn && demo.role !== 'anonymous') {
        message = "You signed in, so the session-only practice ended. Its ratings weren't imported into your account."
      } else if (session.signedIn && demo.role === 'anonymous') {
        message = `You signed out, so practice ended.${saved}`
      } else if (session.dictionaryKey !== demo.dictionaryKey) {
        message = `You switched dictionaries, so practice ended.${saved}`
      } else if (session.learner !== demo.learner && session.signedIn) {
        message = `The signed-in learner changed, so practice ended.${saved}`
      } else if (session.shareKeyVersion !== demo.shareKeyVersion) {
        message = `The share link changed, so practice ended.${saved}`
      } else {
        message = `Your access changed, so practice ended.${saved}`
      }
      setSession(null)
      setEndNotice(message)
      focusTrain()
    },
    [session, demo.role, demo.dictionaryKey, demo.learner, demo.shareKeyVersion, focusTrain],
  )

  const trainMenu = (ref: React.RefObject<HTMLDivElement>, placement: 'top' | 'bottom') => (
    <TrainMenu
      capability={capability}
      archived={dictionary.archived}
      onSelectCards={() => setSetupOpen(true)}
      wrapperRef={ref}
      placement={placement}
    />
  )

  return (
    <>
      <main className="mx-auto flex w-full max-w-app flex-col gap-6 px-4 pb-40 pt-6 md:px-6 lg:px-12">
        {endNotice && (
          <InlineAlert tone="info" title="Practice ended" onDismiss={() => setEndNotice(null)}>
            {endNotice}
          </InlineAlert>
        )}

        <DictionaryHeader
          dictionary={dictionary}
          activeCount={active.length}
          isOwner={isOwner}
          onLibrary={unchanged}
          actions={
            isOwner ? (
              <>
                <IconButton icon={<SettingsIcon />} label="Dictionary settings" variant="outline" size="lg" onClick={unchanged} />
                <IconButton icon={<MoreHorizontalIcon />} label="More actions" variant="outline" size="lg" onClick={unchanged} />
              </>
            ) : (
              <>
                {signedIn ? (
                  <Button variant="secondary" leadingIcon={<CopyIcon className="h-4 w-4" />} onClick={unchanged}>
                    Make a private copy
                  </Button>
                ) : (
                  <Button variant="secondary" leadingIcon={<LogInIcon className="h-4 w-4" />} onClick={() => demo.update({ role: 'reader' })}>
                    Sign in to copy
                  </Button>
                )}
                {trainMenu(readerTrainRef, 'bottom')}
              </>
            )
          }
        />

        {dictionary.archived && isOwner && (
          <InlineAlert tone="info" title="This dictionary is archived">
            Archived dictionaries can't be trained. Restore it from settings to practise again.
          </InlineAlert>
        )}

        <section aria-labelledby="entries-heading" className="flex flex-col gap-4">
          <div className="flex flex-wrap items-end justify-between gap-3">
            <h2 id="entries-heading" className="text-lg font-semibold text-text-primary">
              Cards
            </h2>
            <Input
              type="search"
              aria-label="Search cards"
              placeholder="Search cards"
              value={search}
              onChange={(e) => {
                setSearch(e.target.value)
                setVisible(PAGE)
              }}
              leadingIcon={<SearchIcon className="h-4 w-4" />}
              wrapperClassName="w-full sm:w-72"
            />
          </div>

          {active.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-border-strong bg-background-surface px-6 py-12 text-center">
              <p className="font-medium text-text-primary">No active cards yet</p>
              <p className="mt-1 text-sm text-text-secondary">
                {isOwner ? 'Use Add card to create the first entry.' : 'The owner hasn’t added any cards yet.'}
              </p>
            </div>
          ) : filtered.length === 0 ? (
            <p className="py-8 text-center text-text-secondary">No cards match “{search}”.</p>
          ) : (
            <ul className="flex flex-col gap-3">
              {filtered.slice(0, visible).map((entry) => (
                <li key={entry.entryId}>
                  <EntryCard entry={entry} dictionary={dictionary} isOwner={isOwner} onEntryActions={unchanged} />
                </li>
              ))}
            </ul>
          )}
          {filtered.length > visible && (
            <Button variant="secondary" onClick={() => setVisible((v) => v + PAGE)} className="self-center">
              Show more ({filtered.length - visible} left)
            </Button>
          )}
        </section>
      </main>

      {isOwner && (
        <div className="bottom-safe fixed right-4 z-30 flex items-center gap-3 md:right-8">
          {trainMenu(ownerTrainRef, 'top')}
          <Button
            size="large"
            leadingIcon={<PlusIcon className="h-5 w-5" />}
            onClick={unchanged}
            disabled={dictionary.archived}
            className="shadow-elev-lg"
          >
            Add card
          </Button>
        </div>
      )}

      <SetupDialog
        key={demo.identity}
        open={setupOpen}
        onClose={() => setSetupOpen(false)}
        onStart={handleStart}
        dictionary={dictionary}
        activeCount={active.length}
        signedIn={signedIn}
        scenario={demo.scenario}
      />

      {session && (
        <PracticeSession
          key={session.id}
          sessionId={session.id}
          dictionary={dictionary}
          payload={session.payload}
          signedIn={session.signedIn}
          scenario={demo.scenario}
          identity={demo.identity}
          fullscreenRequest={session.fullscreen}
          onClose={closeSession}
          onForcedEnd={handleForcedEnd}
        />
      )}
    </>
  )
}

