import type { DictionaryRecord, EntryRecord } from '../types/dictionary'
import type { Configuration, Field, Presentation } from '../types/learning'

export const FIELD_ORDER: Field[] = [
  'source',
  'translation',
  'transcription',
  'definition',
  'sourceExample',
  'targetExample',
]

export const FIELD_LABELS: Record<Field, string> = {
  source: 'Source',
  translation: 'Translation',
  transcription: 'Transcription',
  definition: 'Definition',
  sourceExample: 'Source-language example',
  targetExample: 'Target-language example',
}

export const DEFAULT_CONFIGURATION: Configuration = {
  front: ['targetExample'],
  back: ['sourceExample'],
}

export function orderFields(fields: Field[]): Field[] {
  return FIELD_ORDER.filter((field) => fields.includes(field))
}

export function sameFieldSet(a: Field[], b: Field[]): boolean {
  return a.length === b.length && a.every((field) => b.includes(field))
}

export function isField(value: unknown): value is Field {
  return typeof value === 'string' && (FIELD_ORDER as string[]).includes(value)
}

function resolveField(
  entry: EntryRecord,
  field: Field,
  dictionary: DictionaryRecord,
): Presentation | null {
  const src = dictionary.sourceLanguage
  const tgt = dictionary.targetLanguage
  const word = (f: 'source' | 'translation', requested: Field, fallback: boolean): Presentation => ({
    field: f,
    requestedFields: [requested],
    text: f === 'source' ? entry.source : entry.translation,
    language: f === 'source' ? src.code : tgt.code,
    direction: f === 'source' ? src.direction : tgt.direction,
    fallback,
  })

  switch (field) {
    case 'source':
      return word('source', 'source', false)
    case 'translation':
      return word('translation', 'translation', false)
    case 'transcription':
      return entry.transcription
        ? {
            field,
            requestedFields: [field],
            text: entry.transcription,
            language: src.code,
            direction: 'ltr',
            fallback: false,
          }
        : null
    case 'definition':
      return entry.definition
        ? {
            field,
            requestedFields: [field],
            text: entry.definition,
            language: tgt.code,
            direction: tgt.direction,
            fallback: false,
          }
        : null
    case 'sourceExample':
      return !entry.exampleDisabled && entry.sourceExample
        ? {
            field,
            requestedFields: [field],
            text: entry.sourceExample,
            language: src.code,
            direction: src.direction,
            fallback: false,
          }
        : word('source', 'sourceExample', true)
    case 'targetExample':
      return !entry.exampleDisabled && entry.targetExample
        ? {
            field,
            requestedFields: [field],
            text: entry.targetExample,
            language: tgt.code,
            direction: tgt.direction,
            fallback: false,
          }
        : word('translation', 'targetExample', true)
  }
}

/**
 * Builds one card side in canonical presentation order. When a missing example
 * falls back to a word that is also explicitly selected, the word renders once
 * and carries both requested fields.
 */
export function buildSide(
  entry: EntryRecord,
  fields: Field[],
  dictionary: DictionaryRecord,
): Presentation[] {
  const out: Presentation[] = []
  for (const field of orderFields(fields)) {
    const presentation = resolveField(entry, field, dictionary)
    if (!presentation) continue
    const existing = out.find((item) => item.field === presentation.field)
    if (existing) {
      existing.requestedFields = orderFields([
        ...existing.requestedFields,
        ...presentation.requestedFields,
      ])
      existing.fallback = existing.fallback || presentation.fallback
      continue
    }
    out.push(presentation)
  }
  return out
}

export function buildCard(entry: EntryRecord, configuration: Configuration, dictionary: DictionaryRecord) {
  const front = buildSide(entry, configuration.front, dictionary)
  const back = buildSide(entry, configuration.back, dictionary)
  return {
    front,
    back,
    eligible: front.length > 0 && back.length > 0,
    hasFallback: [...front, ...back].some((p) => p.fallback),
  }
}

const LANGUAGE_NAMES: Record<string, string> = {
  es: 'Spanish',
  en: 'English',
  ar: 'Arabic',
  he: 'Hebrew',
}

export function languageName(code: string): string {
  return LANGUAGE_NAMES[code] ?? code.toUpperCase()
}

/** Describes which example a fallback word stands in for. */
export function fallbackNote(presentation: Presentation): string | null {
  if (!presentation.fallback) return null
  const missing = presentation.requestedFields.filter(
    (f) => f === 'sourceExample' || f === 'targetExample',
  )
  if (missing.length === 0) return null
  const names = missing.map((f) => FIELD_LABELS[f]).join(' and ')
  const wordName = FIELD_LABELS[presentation.field].toLowerCase()
  return presentation.requestedFields.includes(presentation.field)
    ? `Also stands in for the ${names}, which is missing for this entry.`
    : `No ${names} for this entry — showing the ${wordName} instead.`
}

files.utils/mockLearningApi.ts:
/**
 * In-memory mock of the Languon learning API. Synthetic, local and asynchronous.
 * It mirrors the implemented request/response shapes but is NOT production proof:
 * nothing is persisted beyond this browser tab.
 */
import { dictionaries } from '../data/dictionaries'
import type { DictionaryKey, DictionaryRecord, EntryRecord } from '../types/dictionary'
import type { LearnerId, Role, Scenario } from '../types/demo'
import type {
  AttemptResponse,
  Configuration,
  EntriesPage,
  ItemsResponse,
  Preferences,
  PrepareResponse,
  Progress,
  Rating,
  Scope,
  UndoResponse,
} from '../types/learning'
import { ApiError } from './apiError'
import { buildCard, DEFAULT_CONFIGURATION, isField } from './flashcardFields'

export interface MockContext {
  role: Role
  learner: LearnerId
  dictionaryKey: DictionaryKey
  scenario: Scenario
  shareKeyVersion: number
}

interface SavedRating {
  rating: Rating
  learningVersion: number
  attemptId: string
}

interface AttemptRecord {
  attemptId: string
  key: string
  entryId: string
  rating: Rating
  learningVersion: number
  previous: SavedRating | null
}

export interface NetworkLogEntry {
  id: number
  method: string
  path: string
  personal: boolean
  shared: boolean
  status: number | 'pending'
  code?: string
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

let context: MockContext = {
  role: 'owner',
  learner: 'A',
  dictionaryKey: 'spanish',
  scenario: 'normal',
  shareKeyVersion: 1,
}

let dicts = buildDictionaries('normal')
const preferences = new Map<string, Preferences>()
const current = new Map<string, SavedRating>()
const attempts = new Map<string, AttemptRecord>()
const operations = new Map<string, { fingerprint: string; result: unknown }>()
let flags = freshFlags()

let revision = 0
let log: NetworkLogEntry[] = []
let logId = 0
const listeners = new Set<() => void>()

function freshFlags() {
  return {
    prepareFailed: false,
    initialLoadFailed: false,
    prefConflict: false,
    saveFailed: false,
    lostResponse: false,
    rateLimited: false,
    idemConflict: false,
    undoConflict: false,
    contentChanged: false,
    removed: false,
    revoked: false,
  }
}

function buildDictionaries(scenario: Scenario): DictionaryRecord[] {
  return dictionaries.map((d) => {
    const copy: DictionaryRecord = {
      ...d,
      sourceLanguage: { ...d.sourceLanguage },
      targetLanguage: { ...d.targetLanguage },
      entries: d.entries.map((e) => ({ ...e })),
    }
    if (scenario === 'archived') copy.archived = true
    if (scenario === 'empty') copy.entries = copy.entries.map((e) => ({ ...e, archived: true }))
    if (scenario === 'zeroEligible')
      copy.entries = copy.entries.map((e) => ({ ...e, definition: undefined }))
    return copy
  })
}

function emit() {
  revision += 1
  listeners.forEach((fn) => fn())
}

export function subscribeMock(fn: () => void) {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}
export const getMockRevision = () => revision
export const getNetworkLog = () => log

export function setMockContext(next: MockContext) {
  const contentChanged =
    next.scenario !== context.scenario || next.dictionaryKey !== context.dictionaryKey
  context = next
  if (contentChanged) {
    dicts = buildDictionaries(next.scenario)
    flags = freshFlags()
    queueMicrotask(emit)
  }
}

export function resetMockData() {
  dicts = buildDictionaries(context.scenario)
  preferences.clear()
  current.clear()
  attempts.clear()
  operations.clear()
  flags = freshFlags()
  log = []
  emit()
}

/** Authoring view read (existing dictionary workspace), not a learning API call. */
export function getWorkspaceDictionary(): DictionaryRecord {
  return dict()
}

function dict(): DictionaryRecord {
  const found = dicts.find((d) => d.key === context.dictionaryKey)
  if (!found) throw new ApiError('dictionary_not_found', 'Not found', 404)
  return found
}

const activeEntries = () => dict().entries.filter((e) => !e.archived)
const isShared = () => context.role !== 'owner'
const learnerKey = () => `${context.learner}:${dict().dictionaryId}`
const ratingKey = (entryId: string) => `${learnerKey()}:${entryId}`

function basePath() {
  const d = dict()
  return isShared()
    ? `/learning/shared-dictionaries/${d.shareId}`
    : `/learning/dictionaries/${d.dictionaryId}`
}

export function newId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID()
  return 'xxxxxxxx-xxxx-4xxx-8xxx-xxxxxxxxxxxx'.replace(/x/g, () =>
    Math.floor(Math.random() * 16).toString(16),
  )
}

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T

async function request<T>(
  method: string,
  path: string,
  options: { personal?: boolean; delay?: number },
  handler: () => T,
): Promise<T> {
  const entry: NetworkLogEntry = {
    id: ++logId,
    method,
    path,
    personal: Boolean(options.personal),
    shared: isShared() && path.startsWith('/learning/shared'),
    status: 'pending',
  }
  log = [entry, ...log].slice(0, 30)
  emit()
  await wait(options.delay ?? 380 + Math.random() * 260)
  try {
    if (options.personal && context.role === 'anonymous') {
      throw new ApiError('authentication_required', 'Sign in required', 401)
    }
    const result = handler()
    entry.status = 200
    log = [...log]
    emit()
    return clone(result)
  } catch (error) {
    if (error instanceof ApiError) {
      entry.status = error.status
      entry.code = error.code
    }
    log = [...log]
    emit()
    throw error
  }
}

function checkAccess() {
  if (flags.revoked || dict().archived) {
    throw isShared()
      ? new ApiError('shared_dictionary_not_found', 'Not found', 404)
      : new ApiError('dictionary_not_found', 'Not found', 404)
  }
}

function validateConfiguration(configuration: Configuration) {
  const valid = (side: unknown) =>
    Array.isArray(side) &&
    side.length > 0 &&
    side.every(isField) &&
    new Set(side).size === side.length
  if (!configuration || !valid(configuration.front) || !valid(configuration.back)) {
    throw new ApiError('invalid_request', 'Invalid configuration', 400)
  }
}

function validateIds(ids: unknown, max: number) {
  if (
    !Array.isArray(ids) ||
    ids.length < 1 ||
    ids.length > max ||
    new Set(ids).size !== ids.length ||
    !ids.every((id) => typeof id === 'string' && UUID_RE.test(id))
  ) {
    throw new ApiError('invalid_request', 'Invalid entry IDs', 400)
  }
}

function findActive(entryId: string): EntryRecord {
  const entry = activeEntries().find((e) => e.entryId === entryId)
  if (!entry) throw new ApiError('entry_not_found', 'Entry not found', 404)
  return entry
}

function replay<T>(operationId: string, fingerprint: string): T | undefined {
  const stored = operations.get(operationId)
  if (!stored) return undefined
  if (stored.fingerprint !== fingerprint) {
    throw new ApiError('idempotency_conflict', 'Operation reused', 409)
  }
  return stored.result as T
}

export const learningApi = {
  getCapabilities: () =>
    request('GET', '/learning/capabilities', {}, () => {
      if (context.scenario === 'backendOff') {
        throw new ApiError('service_unavailable', 'Unavailable', 503)
      }
      return { flashcardsEnabled: context.scenario !== 'capabilityOff' }
    }),

  listEntries: (search: string, cursor: string | null) => {
    const query = new URLSearchParams({ limit: '25' })
    if (search) query.set('search', search)
    if (cursor) query.set('cursor', cursor)
    return request<EntriesPage>('GET', `${basePath()}/entries?${query}`, {}, () => {
      checkAccess()
      const needle = search.trim().toLocaleLowerCase()
      const matches = activeEntries().filter(
        (e) =>
          !needle ||
          e.source.toLocaleLowerCase().includes(needle) ||
          e.translation.toLocaleLowerCase().includes(needle),
      )
      const offset = Number(cursor ?? 0)
      const page = matches.slice(offset, offset + 25)
      return {
        entries: page.map(({ entryId, source, translation }) => ({ entryId, source, translation })),
        nextCursor: offset + 25 < matches.length ? String(offset + 25) : null,
      }
    })
  },

  getPreferences: () =>
    request<Preferences>('GET', `${basePath()}/flashcards/preferences`, { personal: true }, () => {
      checkAccess()
      return (
        preferences.get(learnerKey()) ?? {
          configuration: DEFAULT_CONFIGURATION,
          shuffle: true,
          version: 0,
        }
      )
    }),

  putPreferences: (body: { configuration: Configuration; shuffle: boolean; expectedVersion: number }) =>
    request<Preferences>('PUT', `${basePath()}/flashcards/preferences`, { personal: true }, () => {
      checkAccess()
      validateConfiguration(body.configuration)
      let stored = preferences.get(learnerKey()) ?? {
        configuration: DEFAULT_CONFIGURATION,
        shuffle: true,
        version: 0,
      }
      if (context.scenario === 'preferenceConflict' && !flags.prefConflict) {
        flags.prefConflict = true
        stored = {
          configuration: { front: ['source'], back: ['translation', 'transcription'] },
          shuffle: false,
          version: stored.version + 1,
        }
        preferences.set(learnerKey(), stored)
      }
      if (body.expectedVersion !== stored.version) {
        throw new ApiError('version_conflict', 'Version conflict', 409)
      }
      const next: Preferences = {
        configuration: body.configuration,
        shuffle: body.shuffle,
        version: stored.version + 1,
      }
      preferences.set(learnerKey(), next)
      return next
    }),

  prepare: (body: { configuration: Configuration; scope: Scope }) =>
    request<PrepareResponse>('POST', `${basePath()}/flashcards/prepare`, {}, () => {
      checkAccess()
      if (context.scenario === 'prepareFailure' && !flags.prepareFailed) {
        flags.prepareFailed = true
        throw new ApiError('service_unavailable', 'Unavailable', 503)
      }
      validateConfiguration(body.configuration)
      const active = activeEntries()
      let candidates = active
      let skipped = 0
      if (body.scope.type === 'manual') {
        validateIds(body.scope.entryIds, 10000)
        const wanted = new Set(body.scope.entryIds)
        candidates = active.filter((e) => wanted.has(e.entryId))
        skipped = body.scope.entryIds.length - candidates.length
      }
      const entryIds: string[] = []
      let fallbackCount = 0
      for (const entry of candidates) {
        const card = buildCard(entry, body.configuration, dict())
        if (!card.eligible) {
          skipped += 1
          continue
        }
        entryIds.push(entry.entryId)
        if (card.hasFallback) fallbackCount += 1
      }
      return { entryIds, eligibleCount: entryIds.length, skippedCount: skipped, fallbackCount }
    }),

  getItems: (body: { configuration: Configuration; entryIds: string[] }) =>
    request<ItemsResponse>('POST', `${basePath()}/flashcards/items`, {}, () => {
      checkAccess()
      validateConfiguration(body.configuration)
      validateIds(body.entryIds, 25)
      if (context.scenario === 'initialLoadFailure' && !flags.initialLoadFailed) {
        flags.initialLoadFailed = true
        throw new ApiError('network_timeout', 'Timed out', 0)
      }
      if (context.scenario === 'entriesRemoved' && !flags.removed && body.entryIds.length >= 4) {
        flags.removed = true
        const toRemove = body.entryIds.slice(2, 4)
        dict().entries.forEach((e) => {
          if (toRemove.includes(e.entryId)) e.archived = true
        })
        queueMicrotask(emit)
      }
      const items: ItemsResponse['items'] = []
      const unavailableEntryIds: string[] = []
      for (const id of body.entryIds) {
        const entry = activeEntries().find((e) => e.entryId === id)
        const card = entry ? buildCard(entry, body.configuration, dict()) : null
        if (!entry || !card || !card.eligible) {
          unavailableEntryIds.push(id)
          continue
        }
        items.push({
          entryId: id,
          learningVersion: entry.learningVersion,
          front: card.front,
          back: card.back,
        })
      }
      return { items, unavailableEntryIds }
    }),

  getProgress: () =>
    request<Progress>('GET', `${basePath()}/flashcards/progress`, { personal: true }, () => {
      checkAccess()
      const active = activeEntries()
      let known = 0
      let again = 0
      for (const entry of active) {
        const saved = current.get(ratingKey(entry.entryId))
        if (!saved || saved.learningVersion !== entry.learningVersion) continue
        if (saved.rating === 'known') known += 1
        else again += 1
      }
      return { total: active.length, known, again, unstudied: active.length - known - again }
    }),

  recordAttempt: (body: {
    operationId: string
    sessionId: string
    entryId: string
    expectedLearningVersion: number
    round: number
    rating: Rating
    configuration: Configuration
  }) =>
    request<AttemptResponse>(
      'POST',
      `${basePath()}/flashcards/attempts`,
      { personal: true, delay: context.scenario === 'savePending' ? 3500 : undefined },
      () => {
        checkAccess()
        if (context.scenario === 'rateLimited' && !flags.rateLimited) {
          flags.rateLimited = true
          throw new ApiError('rate_limited', 'Rate limited', 429, 6)
        }
        if (context.scenario === 'saveFailed' && !flags.saveFailed) {
          flags.saveFailed = true
          throw new ApiError('internal_error', 'Server error', 500)
        }
        if (context.scenario === 'idempotencyConflict' && !flags.idemConflict) {
          flags.idemConflict = true
          operations.set(body.operationId, { fingerprint: 'another-request', result: null })
        }
        const fingerprint = JSON.stringify([
          'attempt',
          body.sessionId,
          body.entryId,
          body.rating,
          body.round,
          body.expectedLearningVersion,
        ])
        const replayed = replay<AttemptResponse>(body.operationId, fingerprint)
        if (replayed) return replayed

        const entry = findActive(body.entryId)
        if (context.scenario === 'contentChanged' && !flags.contentChanged) {
          flags.contentChanged = true
          entry.learningVersion += 1
          if (entry.targetExample) entry.targetExample = `${entry.targetExample.replace(/\.$/, '')} and bright.`
          if (entry.sourceExample) entry.sourceExample = `${entry.sourceExample.replace(/\.$/, '')} y luminosa.`
          queueMicrotask(emit)
        }
        if (entry.learningVersion !== body.expectedLearningVersion) {
          throw new ApiError('learning_version_conflict', 'Content changed', 409)
        }
        const key = ratingKey(entry.entryId)
        const attemptId = newId()
        attempts.set(attemptId, {
          attemptId,
          key,
          entryId: entry.entryId,
          rating: body.rating,
          learningVersion: entry.learningVersion,
          previous: current.get(key) ?? null,
        })
        current.set(key, { rating: body.rating, learningVersion: entry.learningVersion, attemptId })
        const result: AttemptResponse = {
          attemptId,
          entryId: entry.entryId,
          learningVersion: entry.learningVersion,
          rating: body.rating,
        }
        operations.set(body.operationId, { fingerprint, result })
        if (context.scenario === 'accessRevoked') flags.revoked = true
        if (context.scenario === 'saveLostResponse' && !flags.lostResponse) {
          flags.lostResponse = true
          throw new ApiError('network_timeout', 'Response lost', 0)
        }
        return result
      },
    ),

  undoAttempt: (attemptId: string, body: { operationId: string }) =>
    request<UndoResponse>(
      'POST',
      `${basePath()}/flashcards/attempts/${attemptId}/undo`,
      { personal: true, delay: context.scenario === 'undoPending' ? 3500 : undefined },
      () => {
        checkAccess()
        const fingerprint = JSON.stringify(['undo', attemptId])
        const replayed = replay<UndoResponse>(body.operationId, fingerprint)
        if (replayed) return replayed
        const record = attempts.get(attemptId)
        if (!record) throw new ApiError('entry_not_found', 'Attempt not found', 404)
        if (context.scenario === 'undoConflict' && !flags.undoConflict) {
          flags.undoConflict = true
          const competingId = newId()
          attempts.set(competingId, { ...record, attemptId: competingId, previous: current.get(record.key) ?? null })
          current.set(record.key, {
            rating: record.rating === 'known' ? 'again' : 'known',
            learningVersion: record.learningVersion,
            attemptId: competingId,
          })
        }
        if (current.get(record.key)?.attemptId !== attemptId) {
          throw new ApiError('undo_conflict', 'Newer result exists', 409)
        }
        if (record.previous) current.set(record.key, record.previous)
        else current.delete(record.key)
        const result: UndoResponse = {
          attemptId,
          entryId: record.entryId,
          learningVersion: record.learningVersion,
          rating: record.previous?.rating ?? null,
        }
        operations.set(body.operationId, { fingerprint, result })
        return result
      },
    ),
}

