import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { Scenario } from '../../../types/demo'
import type { Configuration, Field, Preferences, PrepareResponse, Scope } from '../../../types/learning'
import { ApiError, toApiError } from '../../../utils/apiError'
import { DEFAULT_CONFIGURATION, orderFields, sameFieldSet } from '../../../utils/flashcardFields'
import { learningApi } from '../../../utils/mockLearningApi'

export interface StartPayload {
  configuration: Configuration
  shuffle: boolean
  entryIds: string[]
  prepared: PrepareResponse
}

export interface PrepareState {
  status: 'idle' | 'loading' | 'ready' | 'error'
  result?: PrepareResponse
  error?: ApiError
}

interface Args {
  open: boolean
  signedIn: boolean
  scenario: Scenario
  activeCount: number
}

export function useFlashcardSetup({ open, signedIn, scenario, activeCount }: Args) {
  const [front, setFront] = useState<Field[]>(DEFAULT_CONFIGURATION.front)
  const [back, setBack] = useState<Field[]>(DEFAULT_CONFIGURATION.back)
  const [shuffle, setShuffle] = useState(true)
  const [scopeType, setScopeType] = useState<'all' | 'manual'>('all')
  const [manualIds, setManualIds] = useState<Set<string>>(new Set())
  const [prefsStatus, setPrefsStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [loadAttempt, setLoadAttempt] = useState(0)
  const [savedVersion, setSavedVersion] = useState(0)
  const [conflict, setConflict] = useState<Preferences | null>(null)
  const [conflictBusy, setConflictBusy] = useState(false)
  const [overwriteDone, setOverwriteDone] = useState(false)
  const [prepare, setPrepare] = useState<PrepareState>({ status: 'idle' })
  const [prepareAttempt, setPrepareAttempt] = useState(0)
  const [starting, setStarting] = useState(false)
  const [startError, setStartError] = useState<ApiError | null>(null)
  const requestId = useRef(0)

  // Load remembered settings (signed-in) or defaults (anonymous) each time the dialog opens.
  useEffect(() => {
    if (!open) return
    setScopeType('all')
    setManualIds(new Set())
    setConflict(null)
    setStartError(null)
    setOverwriteDone(false)
    const apply = (cfg: Configuration, sh: boolean) => {
      let next = cfg
      let nextShuffle = sh
      if (scenario === 'zeroEligible') next = { ...next, front: ['definition'] }
      if (scenario === 'missingExample') {
        next = { front: ['translation', 'targetExample'], back: ['sourceExample'] }
        nextShuffle = false
      }
      setFront(next.front)
      setBack(next.back)
      setShuffle(nextShuffle)
    }
    if (!signedIn) {
      apply(DEFAULT_CONFIGURATION, true)
      setSavedVersion(0)
      setPrefsStatus('ready')
      return
    }
    let cancelled = false
    setPrefsStatus('loading')
    learningApi
      .getPreferences()
      .then((prefs) => {
        if (cancelled) return
        apply(prefs.configuration, prefs.shuffle)
        setSavedVersion(prefs.version)
        setPrefsStatus('ready')
      })
      .catch(() => {
        if (cancelled) return
        apply(DEFAULT_CONFIGURATION, true)
        setPrefsStatus('error')
      })
    return () => {
      cancelled = true
    }
  }, [open, signedIn, scenario, loadAttempt])

  const configuration = useMemo<Configuration>(
    () => ({ front: orderFields(front), back: orderFields(back) }),
    [front, back],
  )
  const frontError = front.length === 0 ? 'Choose at least one field for the front.' : undefined
  const backError = back.length === 0 ? 'Choose at least one field for the back.' : undefined
  const identicalSides = front.length > 0 && sameFieldSet(front, back)
  const scopeEmpty = scopeType === 'manual' && manualIds.size === 0
  const canPrepare =
    open && prefsStatus !== 'loading' && !frontError && !backError && !scopeEmpty && activeCount > 0

  const scope = useMemo<Scope>(
    () => (scopeType === 'all' ? { type: 'all' } : { type: 'manual', entryIds: [...manualIds] }),
    [scopeType, manualIds],
  )

  // Live preview of eligible / skipped / fallback counts.
  useEffect(() => {
    if (!canPrepare) {
      setPrepare({ status: 'idle' })
      return
    }
    const id = ++requestId.current
    setPrepare((prev) => ({ status: 'loading', result: prev.result }))
    const timer = window.setTimeout(() => {
      learningApi
        .prepare({ configuration, scope })
        .then((result) => {
          if (id === requestId.current) setPrepare({ status: 'ready', result })
        })
        .catch((error) => {
          if (id === requestId.current) setPrepare({ status: 'error', error: toApiError(error) })
        })
    }, 350)
    return () => window.clearTimeout(timer)
  }, [canPrepare, configuration, scope, prepareAttempt])

  const start = useCallback(async (): Promise<StartPayload | null> => {
    setStarting(true)
    setStartError(null)
    try {
      if (signedIn) {
        try {
          const saved = await learningApi.putPreferences({
            configuration,
            shuffle,
            expectedVersion: savedVersion,
          })
          setSavedVersion(saved.version)
        } catch (error) {
          const err = toApiError(error)
          if (err.code !== 'version_conflict') throw err
          setConflict(await learningApi.getPreferences())
          return null
        }
      }
      requestId.current += 1
      const result = await learningApi.prepare({ configuration, scope })
      setPrepare({ status: 'ready', result })
      if (result.eligibleCount === 0) return null
      return { configuration, shuffle, entryIds: result.entryIds, prepared: result }
    } catch (error) {
      setStartError(toApiError(error))
      return null
    } finally {
      setStarting(false)
    }
  }, [signedIn, configuration, shuffle, savedVersion, scope])

  const reloadSaved = useCallback(() => {
    if (!conflict) return
    setFront(conflict.configuration.front)
    setBack(conflict.configuration.back)
    setShuffle(conflict.shuffle)
    setSavedVersion(conflict.version)
    setConflict(null)
  }, [conflict])

  const overwrite = useCallback(async () => {
    if (!conflict) return
    setConflictBusy(true)
    try {
      const saved = await learningApi.putPreferences({
        configuration,
        shuffle,
        expectedVersion: conflict.version,
      })
      setSavedVersion(saved.version)
      setConflict(null)
      setOverwriteDone(true)
    } catch (error) {
      const err = toApiError(error)
      if (err.code === 'version_conflict') setConflict(await learningApi.getPreferences())
      else setStartError(err)
    } finally {
      setConflictBusy(false)
    }
  }, [conflict, configuration, shuffle])

  const toggleManual = useCallback((entryId: string) => {
    setManualIds((prev) => {
      const next = new Set(prev)
      if (next.has(entryId)) next.delete(entryId)
      else next.add(entryId)
      return next
    })
  }, [])

  const setManualMany = useCallback((ids: string[], selected: boolean) => {
    setManualIds((prev) => {
      const next = new Set(prev)
      ids.forEach((id) => (selected ? next.add(id) : next.delete(id)))
      return next
    })
  }, [])

  return {
    front,
    back,
    setFront,
    setBack,
    shuffle,
    setShuffle,
    scopeType,
    setScopeType,
    manualIds,
    toggleManual,
    setManualMany,
    clearManual: () => setManualIds(new Set()),
    prefsStatus,
    retryPrefs: () => setLoadAttempt((n) => n + 1),
    conflict,
    conflictBusy,
    overwriteDone,
    reloadSaved,
    overwrite,
    prepare,
    retryPrepare: () => setPrepareAttempt((n) => n + 1),
    frontError,
    backError,
    identicalSides,
    scopeEmpty,
    starting,
    startError,
    start,
    canStart:
      !frontError &&
      !backError &&
      !scopeEmpty &&
      activeCount > 0 &&
      prefsStatus !== 'loading' &&
      !conflict &&
      !(prepare.status === 'ready' && prepare.result?.eligibleCount === 0),
  }
}

files.components/training/PracticeSession/useP:
import { useCallback, useEffect, useRef, useState } from 'react'
import type { Configuration, Face, FlashcardItem, Progress, Rating } from '../../../types/learning'
import { ApiError, isAccessLoss, toApiError } from '../../../utils/apiError'
import { learningApi, newId } from '../../../utils/mockLearningApi'
import { shuffled } from '../../../utils/shuffle'

export interface SessionInput {
  sessionId: string
  configuration: Configuration
  shuffle: boolean
  entryIds: string[]
  signedIn: boolean
}

export type Phase = 'loading' | 'card' | 'results' | 'error' | 'unavailable'

export interface RoundStats {
  reviewed: number
  known: number
  again: number
}

interface Snapshot {
  index: number
  face: Face
  roundStats: RoundStats
  outcomes: Record<string, Rating>
  reviewEvents: number
}

export interface AckedRating {
  attemptId: string | null
  entryId: string
  rating: Rating
  snapshot: Snapshot
}

export interface Pending {
  kind: 'rate' | 'undo'
  rating: Rating
  entryId: string
  operationId: string
  status: 'saving' | 'error'
  error?: ApiError
  retryAt?: number
}

export type ConflictKind = 'content' | 'operation' | 'undo'

export interface SessionState {
  phase: Phase
  round: number
  allIds: string[]
  queue: string[]
  index: number
  face: Face
  items: Record<string, FlashcardItem>
  itemsLoading: boolean
  roundStats: RoundStats
  outcomes: Record<string, Rating>
  reviewEvents: number
  roundsCompleted: number
  savedCount: number
  lastAck: AckedRating | null
  pending: Pending | null
  conflict: ConflictKind | null
  conflictBusy: boolean
  notices: string[]
  error: ApiError | null
  errorRetryAt?: number
  progress: Progress | null
  progressStatus: 'idle' | 'loading' | 'error'
  announcement: string
}

const BATCH = 25
const EMPTY_STATS: RoundStats = { reviewed: 0, known: 0, again: 0 }
export const RATING_LABEL: Record<Rating, string> = { known: 'Known', again: 'Practise again' }

const retryAtFor = (error: ApiError) =>
  error.retryAfterSeconds ? Date.now() + error.retryAfterSeconds * 1000 : undefined

export function usePracticeSession(input: SessionInput) {
  const [state, setState] = useState<SessionState>(() => ({
    phase: input.entryIds.length ? 'loading' : 'results',
    round: 1,
    allIds: input.entryIds,
    queue: input.shuffle ? shuffled(input.entryIds) : input.entryIds,
    index: 0,
    face: 'front',
    items: {},
    itemsLoading: false,
    roundStats: EMPTY_STATS,
    outcomes: {},
    reviewEvents: 0,
    roundsCompleted: 0,
    savedCount: 0,
    lastAck: null,
    pending: null,
    conflict: null,
    conflictBusy: false,
    notices: [],
    error: null,
    progress: null,
    progressStatus: 'idle',
    announcement: '',
  }))
  const ref = useRef(state)
  ref.current = state
  const mounted = useRef(true)
  const inFlight = useRef(false)

  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
    }
  }, [])

  const patch = useCallback((fn: (prev: SessionState) => Partial<SessionState>) => {
    if (mounted.current) setState((prev) => ({ ...prev, ...fn(prev) }))
  }, [])

  const becomeUnavailable = useCallback(() => {
    patch(() => ({
      phase: 'unavailable',
      items: {},
      queue: [],
      pending: null,
      conflict: null,
      lastAck: null,
      itemsLoading: false,
      announcement: 'Practice ended. This dictionary is no longer available.',
    }))
  }, [patch])

  const refreshProgress = useCallback(async () => {
    if (!input.signedIn) return
    patch(() => ({ progressStatus: 'loading' }))
    try {
      const progress = await learningApi.getProgress()
      patch(() => ({ progress, progressStatus: 'idle' }))
    } catch (e) {
      const err = toApiError(e)
      if (isAccessLoss(err)) becomeUnavailable()
      else patch(() => ({ progressStatus: 'error' }))
    }
  }, [input.signedIn, patch, becomeUnavailable])

  const skipNotice = (count: number) =>
    `${count} ${count === 1 ? 'card was' : 'cards were'} removed or no longer eligible, so ${
      count === 1 ? 'it was' : 'they were'
    } skipped.`

  const loadItems = useCallback(
    async (index: number, queue: string[]) => {
      const needed = queue.slice(index, index + BATCH).filter((id) => !ref.current.items[id])
      if (needed.length === 0) return
      patch(() => ({ itemsLoading: true, error: null }))
      try {
        const res = await learningApi.getItems({ configuration: input.configuration, entryIds: needed })
        if (!mounted.current) return
        setState((prev) => {
          const items = { ...prev.items }
          res.items.forEach((item) => {
            items[item.entryId] = item
          })
          const gone = new Set(res.unavailableEntryIds)
          const nextQueue = prev.queue.filter((id) => !gone.has(id))
          const done = prev.index >= nextQueue.length
          return {
            ...prev,
            items,
            queue: nextQueue,
            allIds: prev.allIds.filter((id) => !gone.has(id)),
            notices: gone.size ? [...prev.notices, skipNotice(gone.size)] : prev.notices,
            itemsLoading: false,
            phase: done ? 'results' : 'card',
            roundsCompleted: done && prev.phase !== 'results' ? prev.roundsCompleted + 1 : prev.roundsCompleted,
            announcement: done
              ? 'Round complete.'
              : `Card ${prev.index + 1} of ${nextQueue.length}. Front.`,
          }
        })
      } catch (e) {
        const err = toApiError(e)
        if (isAccessLoss(err)) becomeUnavailable()
        else
          patch(() => ({
            itemsLoading: false,
            phase: 'error',
            error: err,
            errorRetryAt: retryAtFor(err),
            announcement: 'Cards could not be loaded.',
          }))
      }
    },
    [input.configuration, patch, becomeUnavailable],
  )

  // Fetch bounded content whenever the current card isn't loaded yet.
  useEffect(() => {
    if ((state.phase !== 'card' && state.phase !== 'loading') || state.itemsLoading) return
    if (state.index >= state.queue.length) {
      patch((prev) => ({ phase: 'results', roundsCompleted: prev.roundsCompleted + 1 }))
      return
    }
    const id = state.queue[state.index]
    if (!state.items[id]) void loadItems(state.index, state.queue)
    else if (state.phase === 'loading') patch(() => ({ phase: 'card' }))
  }, [state.phase, state.index, state.queue, state.items, state.itemsLoading, loadItems, patch])

  useEffect(() => {
    void refreshProgress()
  }, [refreshProgress])

  const applyRating = useCallback(
    (rating: Rating, attemptId: string | null) => {
      patch((prev) => {
        const entryId = prev.queue[prev.index]
        const snapshot: Snapshot = {
          index: prev.index,
          face: prev.face,
          roundStats: prev.roundStats,
          outcomes: prev.outcomes,
          reviewEvents: prev.reviewEvents,
        }
        const nextIndex = prev.index + 1
        const done = nextIndex >= prev.queue.length
        const saved = attemptId ? ', saved' : ''
        return {
          roundStats: {
            reviewed: prev.roundStats.reviewed + 1,
            known: prev.roundStats.known + (rating === 'known' ? 1 : 0),
            again: prev.roundStats.again + (rating === 'again' ? 1 : 0),
          },
          outcomes: { ...prev.outcomes, [entryId]: rating },
          reviewEvents: prev.reviewEvents + 1,
          savedCount: prev.savedCount + (attemptId ? 1 : 0),
          lastAck: { attemptId, entryId, rating, snapshot },
          pending: null,
          index: nextIndex,
          face: 'front',
          phase: done ? 'results' : 'card',
          roundsCompleted: done ? prev.roundsCompleted + 1 : prev.roundsCompleted,
          announcement: done
            ? `Rated ${RATING_LABEL[rating]}${saved}. Round complete.`
            : `Rated ${RATING_LABEL[rating]}${saved}. Card ${nextIndex + 1} of ${prev.queue.length}. Front.`,
        }
      })
    },
    [patch],
  )

  const removeCurrent = useCallback(
    (message: string) => {
      patch((prev) => {
        const entryId = prev.queue[prev.index]
        const queue = prev.queue.filter((id) => id !== entryId)
        const done = prev.index >= queue.length
        return {
          queue,
          allIds: prev.allIds.filter((id) => id !== entryId),
          pending: null,
          conflict: null,
          face: 'front',
          notices: [...prev.notices, message],
          phase: done ? 'results' : 'card',
          roundsCompleted: done ? prev.roundsCompleted + 1 : prev.roundsCompleted,
          announcement: message,
        }
      })
    },
    [patch],
  )

  const submitRating = useCallback(
    async (pending: Pending) => {
      const item = ref.current.items[pending.entryId]
      if (!item) return
      inFlight.current = true
      try {
        const res = await learningApi.recordAttempt({
          operationId: pending.operationId,
          sessionId: input.sessionId,
          entryId: pending.entryId,
          expectedLearningVersion: item.learningVersion,
          round: ref.current.round,
          rating: pending.rating,
          configuration: input.configuration,
        })
        if (!mounted.current) return
        applyRating(pending.rating, res.attemptId)
        void refreshProgress()
      } catch (e) {
        const err = toApiError(e)
        if (err.code === 'learning_version_conflict') {
          patch(() => ({
            pending: null,
            conflict: 'content',
            announcement: 'This card changed. Load the updated card before rating.',
          }))
        } else if (err.code === 'idempotency_conflict') {
          patch(() => ({
            pending: null,
            conflict: 'operation',
            announcement: 'That rating could not be confirmed.',
          }))
          void refreshProgress()
        } else if (err.code === 'entry_not_found') {
          removeCurrent('This entry was removed, so it was skipped. No rating was saved for it.')
        } else if (isAccessLoss(err)) {
          becomeUnavailable()
        } else {
          patch(() => ({
            pending: { ...pending, status: 'error', error: err, retryAt: retryAtFor(err) },
            announcement: `${RATING_LABEL[pending.rating]} was not confirmed. Retry is available.`,
          }))
        }
      } finally {
        inFlight.current = false
      }
    },
    [input.sessionId, input.configuration, applyRating, refreshProgress, patch, removeCurrent, becomeUnavailable],
  )

  const restore = useCallback(
    (ack: AckedRating, saved: boolean) => {
      patch((prev) => ({
        index: ack.snapshot.index,
        face: ack.snapshot.face,
        roundStats: ack.snapshot.roundStats,
        outcomes: ack.snapshot.outcomes,
        reviewEvents: ack.snapshot.reviewEvents,
        savedCount: prev.savedCount - (saved ? 1 : 0),
        roundsCompleted:
          prev.phase === 'results' ? Math.max(0, prev.roundsCompleted - 1) : prev.roundsCompleted,
        lastAck: null,
        pending: null,
        conflict: null,
        phase: 'card',
        announcement: `Undid ${RATING_LABEL[ack.rating]}. Card ${ack.snapshot.index + 1} of ${prev.queue.length}.`,
      }))
    },
    [patch],
  )

  const submitUndo = useCallback(
    async (pending: Pending, ack: AckedRating) => {
      if (!ack.attemptId) return
      inFlight.current = true
      try {
        await learningApi.undoAttempt(ack.attemptId, { operationId: pending.operationId })
        if (!mounted.current) return
        restore(ack, true)
        void refreshProgress()
      } catch (e) {
        const err = toApiError(e)
        if (err.code === 'undo_conflict' || err.code === 'learning_version_conflict') {
          patch(() => ({
            pending: null,
            lastAck: null,
            conflict: 'undo',
            announcement: 'Undo is no longer possible. Nothing was overwritten.',
          }))
          void refreshProgress()
        } else if (isAccessLoss(err)) {
          becomeUnavailable()
        } else {
          patch(() => ({
            pending: { ...pending, status: 'error', error: err, retryAt: retryAtFor(err) },
            announcement: 'Undo was not confirmed. Retry is available.',
          }))
        }
      } finally {
        inFlight.current = false
      }
    },
    [restore, refreshProgress, patch, becomeUnavailable],
  )

  const rate = useCallback(
    (rating: Rating) => {
      const st = ref.current
      if (st.phase !== 'card' || st.pending || st.conflict || inFlight.current) return
      const entryId = st.queue[st.index]
      if (!entryId || !st.items[entryId]) return
      if (!input.signedIn) {
        applyRating(rating, null)
        return
      }
      const pending: Pending = {
        kind: 'rate',
        rating,
        entryId,
        operationId: newId(),
        status: 'saving',
      }
      patch(() => ({ pending, announcement: `Saving ${RATING_LABEL[rating]}.` }))
      void submitRating(pending)
    },
    [input.signedIn, applyRating, patch, submitRating],
  )

  const undo = useCallback(() => {
    const st = ref.current
    if (!st.lastAck || st.pending || inFlight.current) return
    if (!input.signedIn || !st.lastAck.attemptId) {
      restore(st.lastAck, false)
      return
    }
    const pending: Pending = {
      kind: 'undo',
      rating: st.lastAck.rating,
      entryId: st.lastAck.entryId,
      operationId: newId(),
      status: 'saving',
    }
    patch(() => ({ pending, announcement: 'Undoing last rating.' }))
    void submitUndo(pending, st.lastAck)
  }, [input.signedIn, restore, patch, submitUndo])

  /** Retries the same choice with the same operation ID (idempotent). */
  const retry = useCallback(() => {
    const st = ref.current
    const pending = st.pending
    if (!pending || pending.status !== 'error' || inFlight.current) return
    if (pending.retryAt && pending.retryAt > Date.now()) return
    const next: Pending = { ...pending, status: 'saving', error: undefined, retryAt: undefined }
    patch(() => ({ pending: next, announcement: 'Retrying.' }))
    if (pending.kind === 'rate') void submitRating(next)
    else if (st.lastAck) void submitUndo(next, st.lastAck)
  }, [patch, submitRating, submitUndo])

  const flip = useCallback(() => {
    const st = ref.current
    if (st.phase !== 'card' || st.pending?.status === 'saving' || !st.items[st.queue[st.index]]) return
    const face: Face = st.face === 'front' ? 'back' : 'front'
    patch(() => ({ face, announcement: face === 'front' ? 'Showing front.' : 'Showing back.' }))
  }, [patch])

  const resolveContentConflict = useCallback(async () => {
    const st = ref.current
    const entryId = st.queue[st.index]
    if (!entryId) return
    patch(() => ({ conflictBusy: true }))
    try {
      const res = await learningApi.getItems({ configuration: input.configuration, entryIds: [entryId] })
      const item = res.items[0]
      if (!item) {
        patch(() => ({ conflictBusy: false }))
        removeCurrent('This entry is no longer eligible, so it was skipped.')
        return
      }
      patch((prev) => ({
        items: { ...prev.items, [entryId]: item },
        face: 'front',
        conflict: null,
        conflictBusy: false,
        announcement: 'Updated card loaded. Front.',
      }))
      void refreshProgress()
    } catch (e) {
      const err = toApiError(e)
      if (isAccessLoss(err)) becomeUnavailable()
      else
        patch((prev) => ({
          conflictBusy: false,
          notices: [...prev.notices, 'The updated card could not be loaded. Try again.'],
        }))
    }
  }, [input.configuration, patch, removeCurrent, refreshProgress, becomeUnavailable])

  const dismissConflict = useCallback(() => {
    patch(() => ({ conflict: null }))
    void refreshProgress()
  }, [patch, refreshProgress])

  const startRound = useCallback(
    (ids: string[]) => {
      patch((prev) => ({
        round: prev.round + 1,
        queue: input.shuffle ? shuffled(ids) : ids,
        index: 0,
        face: 'front',
        roundStats: EMPTY_STATS,
        lastAck: null,
        pending: null,
        conflict: null,
        phase: ids.length ? 'loading' : 'results',
        announcement: `Round ${prev.round + 1} started with ${ids.length} cards.`,
      }))
    },
    [input.shuffle, patch],
  )

  const practiseAgain = useCallback(() => {
    const st = ref.current
    startRound(st.allIds.filter((id) => st.outcomes[id] === 'again'))
  }, [startRound])

  const startOver = useCallback(() => startRound(ref.current.allIds), [startRound])

  const retryLoad = useCallback(() => {
    const st = ref.current
    if (st.errorRetryAt && st.errorRetryAt > Date.now()) return
    patch(() => ({ error: null, errorRetryAt: undefined, phase: 'loading' }))
  }, [patch])

  const dismissNotice = useCallback(
    (index: number) => patch((prev) => ({ notices: prev.notices.filter((_, i) => i !== index) })),
    [patch],
  )

  const currentId = state.queue[state.index]
  return {
    state,
    currentItem: currentId ? state.items[currentId] : undefined,
    flip,
    rate,
    undo,
    retry,
    resolveContentConflict,
    dismissConflict,
    practiseAgain,
    startOver,
    retryLoad,
    refreshProgress,
    dismissNotice,
  }
}

