import { useCallback, useEffect, useState } from 'react'
import type { DisplayMode } from '../../../types/demo'
import { exitAppFullscreen, requestAppFullscreen } from '../../../utils/fullscreen'

const FALLBACK_NOTICE =
  "Fullscreen isn't available here, so practice fills this window instead. Mobile browsers may not support fullscreen."

/**
 * Tracks fullscreen / full-window overlay / dialog presentation. Switching modes never
 * touches session state, so queue position, card face and stats are preserved.
 */
export function useDisplayMode(fullscreenRequest: Promise<boolean>, simulateReject: boolean) {
  const [mode, setMode] = useState<DisplayMode>('overlay')
  const [notice, setNotice] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    fullscreenRequest.then((granted) => {
      if (cancelled) return
      if (granted) setMode('fullscreen')
      else setNotice(FALLBACK_NOTICE)
    })
    return () => {
      cancelled = true
    }
  }, [fullscreenRequest])

  // Native Escape (or any browser exit) leaves fullscreen for dialog view, not End.
  useEffect(() => {
    const onChange = () => {
      if (!document.fullscreenElement) setMode((m) => (m === 'fullscreen' ? 'dialog' : m))
    }
    document.addEventListener('fullscreenchange', onChange)
    return () => {
      document.removeEventListener('fullscreenchange', onChange)
      exitAppFullscreen()
    }
  }, [])

  const toDialog = useCallback(() => {
    exitAppFullscreen()
    setMode('dialog')
  }, [])

  /** Must be called directly from a click so the browser sees a user gesture. */
  const toFullscreen = useCallback(() => {
    requestAppFullscreen(simulateReject).then((granted) => {
      setMode(granted ? 'fullscreen' : 'overlay')
      setNotice(granted ? null : FALLBACK_NOTICE)
    })
  }, [simulateReject])

  return { mode, notice, dismissNotice: () => setNotice(null), toDialog, toFullscreen }
}

