import { useCallback, useEffect, useState } from 'react'
import { learningApi } from '../utils/mockLearningApi'

export type CapabilityStatus = 'loading' | 'ready' | 'error'

export interface CapabilityState {
  status: CapabilityStatus
  flashcardsEnabled: boolean
  retry: () => void
}

export function useCapabilities(dependencyKey: string): CapabilityState {
  const [status, setStatus] = useState<CapabilityStatus>('loading')
  const [enabled, setEnabled] = useState(false)
  const [attempt, setAttempt] = useState(0)

  useEffect(() => {
    let cancelled = false
    setStatus('loading')
    learningApi
      .getCapabilities()
      .then((res) => {
        if (cancelled) return
        setEnabled(res.flashcardsEnabled)
        setStatus('ready')
      })
      .catch(() => {
        if (!cancelled) setStatus('error')
      })
    return () => {
      cancelled = true
    }
  }, [dependencyKey, attempt])

  const retry = useCallback(() => setAttempt((n) => n + 1), [])
  return { status, flashcardsEnabled: enabled, retry }
}

