import React from 'react'
import { GraduationCapIcon, LayersIcon, MessageSquareTextIcon, RefreshCwIcon } from 'lucide-react'
import type { CapabilityState } from '../../hooks/useCapabilities'
import { DropdownMenu, DropdownMenuItem, DropdownMenuLabel } from '../DropdownMenu'

interface TrainMenuProps {
  capability: CapabilityState
  archived: boolean
  onSelectCards: () => void
  /** Wrapper ref so focus can return to the Train trigger when practice closes. */
  wrapperRef: React.RefObject<HTMLDivElement>
  placement?: 'top' | 'bottom'
}

export function TrainMenu({ capability, archived, onSelectCards, wrapperRef, placement = 'bottom' }: TrainMenuProps) {
  return (
    <div ref={wrapperRef} className="relative">
      <DropdownMenu
        align="end"
        label={
          <span className="inline-flex items-center gap-2">
            <GraduationCapIcon className="h-4 w-4" aria-hidden />
            Train
          </span>
        }
        className="[&>button]:min-h-11"
        menuClassName={`min-w-56 ${placement === 'top' ? 'bottom-full top-auto mb-2 mt-0' : ''}`}
      >
        <DropdownMenuLabel>Train with</DropdownMenuLabel>
        {capability.status === 'loading' && <DropdownMenuItem disabled>Checking availability…</DropdownMenuItem>}
        {capability.status === 'error' && (
          <DropdownMenuItem icon={<RefreshCwIcon className="h-4 w-4" />} onSelect={capability.retry} closeOnSelect={false}>
            Cards unavailable — Retry
          </DropdownMenuItem>
        )}
        {capability.status === 'ready' && capability.flashcardsEnabled && (
          <DropdownMenuItem
            icon={<LayersIcon className="h-4 w-4" />}
            disabled={archived}
            shortcut={archived ? 'Archived' : undefined}
            onSelect={onSelectCards}
          >
            Cards
          </DropdownMenuItem>
        )}
        <DropdownMenuItem icon={<MessageSquareTextIcon className="h-4 w-4" />} disabled shortcut="Coming soon">
          Sentences
        </DropdownMenuItem>
      </DropdownMenu>
    </div>
  )
}
